                            TargetExpression(text: "I've got …", meaning: "I have: family, pets, things.", note: "I've got two brothers."),
                            TargetExpression(text: "She's / He's got …", meaning: "has got with one person.", note: "He's got a beard."),
                            TargetExpression(text: "Have you got …?", meaning: "Ask about family or things.", note: "Have you got any pets?"),
                            TargetExpression(text: "haven't got / hasn't got", meaning: "Say what you don't have.", note: "I haven't got siblings."),
                            TargetExpression(text: "any", meaning: "With questions and negatives.", note: "Have you got any cousins?"),
                            TargetExpression(text: "the youngest / the oldest", meaning: "Order in the family.", note: "I'm the youngest of three.")],
                situation: "You swap family photos: describe your family, ask about the learner's, and compare what you both have.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Tell me about your family — have you got brothers or sisters?", expected: ["I've got <number> brother(s).", "I haven't got any siblings.", "I'm an only child."], focus: "have got + family", watch: "“I have two brother” — plural -s and got: “I've got two brothers”."),
                                PracticeQuestion(prompt: "Have you got any pets?", expected: ["Yes, I've got a <pet>.", "No, I haven't got any pets."], focus: "any with questions", watch: "“Have you got some pets?” — questions use any."),
                                PracticeQuestion(prompt: "Has your mum got a car?", expected: ["Yes, she has.", "No, she hasn't."], focus: "has short answers", watch: "“Yes, she got” — short answers repeat has."),
                                PracticeQuestion(prompt: "Are you the oldest, the youngest or in the middle?", expected: ["I'm the oldest of three.", "I'm in the middle.", "I'm an only child."], focus: "family position", watch: "“I am more old” — “the oldest”."),
                                PracticeQuestion(prompt: "Have your parents got a garden?", expected: ["Yes, they have. They've got flowers.", "No, they haven't."], focus: "they + have got", watch: "“They has got” — plural takes have."),
                                PracticeQuestion(prompt: "I've got a big family — six of us! And you?", expected: ["We are <number>.", "There are <number> of us."], focus: "saying family size", watch: "“We is five” — “we are five”.")]),
                exercises: [
                            Exercise(id: "en-foundations-u2-have-got-e1", kind: "choice", prompt: "She ___ got two brothers.", options: ["has", "have", "is", "does"], answers: ["has"], explain: "With he/she/it: has got."),
                            Exercise(id: "en-foundations-u2-have-got-e2", kind: "gap", prompt: "I ___ got a big family.", options: [], answers: ["have"], explain: "With I/you/we/they: have got."),
                            Exercise(id: "en-foundations-u2-have-got-e3", kind: "order", prompt: "Ask about sisters.", options: [], answers: ["Have you got any sisters"], explain: "Have + you + got + any + plural."),
                            Exercise(id: "en-foundations-u2-have-got-e4", kind: "written", prompt: "Say how many brothers or sisters you have got.", options: [], answers: ["I've got <number> brothers and <number> sisters", "I've got <number> brother and <number> sister", "I haven't got any brothers or sisters"], explain: "I've got + number + family word.")], skills: ["grammar:have-got", "vocab:family", "function:describe-people"], canDo: ["describe-people"], prerequisites: ["grammar:articles"])])
