public enum EnFoundationsU3 {
    public static let unit: CourseUnit = CourseUnit(id: "en-foundations-u3", title: "Everyday actions", subtitle: "Your week, out loud", level: "A1", themes: [
                    ConversationTheme("morning-rush", "The morning rush", "Against the clock", "sunrise", "Course", "It's 7:40 and you both have somewhere to be. Describe your morning routine while the clock runs.", 0),
                    ConversationTheme("evening-wind-down", "After work", "The quiet hours", "moon.stars", "Course", "It's the end of the day. Tell each other what you do in the evening and how you unwind.", 1)], lessons: [
            Lesson(id: "en-foundations-u3-present", title: "Present simple: I / you / we / they", goal: "Talk about routines and facts with I/you/we/they, and ask with do.",
                intro: LessonIntro(explanation: [
                            "The present simple is for habits and facts: “I work in a bank.” “We live near the park.” With I, you, we and they the verb has no ending.",
                            "Questions and negatives use do: “Do you like coffee?” “I don't eat meat.” The main verb goes back to its simple form.",
                            "Short answers repeat do: “Do you speak English?” — “Yes, I do.” / “No, I don't.”"], examples: [
                            ExampleLine(text: "I work from home.", meaning: "Habit, no ending."),
                            ExampleLine(text: "Do you live alone?", meaning: "Question with do."),
                            ExampleLine(text: "We don't watch TV.", meaning: "Negative with don't."),
                            ExampleLine(text: "They play football on Saturdays.", meaning: "Routine + plural."),
                            ExampleLine(text: "Yes, I do.", meaning: "Short answer."),
                            ExampleLine(text: "You know the answer.", meaning: "Fact with you.")]),
                expressions: [
                            TargetExpression(text: "I work / live / study …", meaning: "Habits with no ending.", note: "I live with two friends."),
                            TargetExpression(text: "Do you …?", meaning: "Ask about routines.", note: "Do you work nearby?"),
                            TargetExpression(text: "I don't …", meaning: "Negative habits.", note: "I don't drink coffee."),
                            TargetExpression(text: "Yes, I do. / No, I don't.", meaning: "Short answers with do.", note: "Repeat do, not the verb."),
                            TargetExpression(text: "on Mondays / at weekends", meaning: "When habits happen.", note: "I play tennis on Sundays."),
                            TargetExpression(text: "What do you do?", meaning: "Ask about someone's job.", note: "Answer: “I'm a …”.")],
                situation: "Two neighbours chat in the square about their week: jobs, habits and what they never do.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "So, what do you do?", expected: ["I'm a <job>.", "I work as a <job>.", "I'm a student."], focus: "asking about jobs", watch: "“What you do?” — questions need do."),
                                PracticeQuestion(prompt: "Do you like your job?", expected: ["Yes, I do.", "No, I don't.", "It's OK."], focus: "like + do short answers", watch: "“Yes, I like” — short answer is “Yes, I do”."),
                                PracticeQuestion(prompt: "Where do you work?", expected: ["I work <place>.", "I work from home.", "I don't work — I study."], focus: "where + do", watch: "“I work in home” — “from home”."),
