                            Exercise(id: "en-foundations-town-hometown-e2", kind: "gap", prompt: "I love my town ___ everything is close. (reason)", options: [], answers: ["because"], explain: "because + reason."),
                            Exercise(id: "en-foundations-town-hometown-e3", kind: "order", prompt: "Describe the people.", options: [], answers: ["The people are very friendly"], explain: "the people are + adjective."),
