                exercises: [
                            Exercise(id: "en-foundations-friends-family-e1", kind: "choice", prompt: "My father ___ sixty years old.", options: ["is", "has", "are", "does"], answers: ["is"], explain: "Age with be: is sixty."),
                            Exercise(id: "en-foundations-friends-family-e2", kind: "gap", prompt: "There ___ five of us in my family.", options: [], answers: ["are", "'re"], explain: "There are five of us."),
                            Exercise(id: "en-foundations-friends-family-e3", kind: "order", prompt: "Say your position in the family.", options: [], answers: ["I'm the youngest in my family"], explain: "I'm the youngest."),
                            Exercise(id: "en-foundations-friends-family-e4", kind: "written", prompt: "Describe one family member in one sentence.", options: [], answers: ["my <relative> is <detail>", "my sister is very funny"], explain: "One detail is enough.")], skills: ["vocab:family", "grammar:verb-be", "grammar:have-got", "function:describe-people"], canDo: ["describe-people"], prerequisites: ["grammar:verb-be"]),
            Lesson(id: "en-foundations-friends-likes", title: "What do you like?", goal: "Talk about likes and dislikes with love, like, don't like and hate.",
                intro: LessonIntro(explanation: [
                            "The pattern: subject + love/like/don't like/hate + noun or verb-ing: “I love music.” “She likes dancing.”",
                            "Ask: “Do you like…?” Short answers repeat do: “Yes, I do. / No, I don't.”",
                            "Strong words: love is 100%, like is warm, don't like is polite, hate is strong — use hate for fun, carefully."], examples: [
