                            ExampleLine(text: "I don't like coffee.", meaning: "Polite negative."),
                            ExampleLine(text: "Do you like football?", meaning: "The question."),
                            ExampleLine(text: "I hate Mondays!", meaning: "Strong — often funny."),
                            ExampleLine(text: "I quite like her podcasts.", meaning: "quite softens like.")]),
                expressions: [
                            TargetExpression(text: "I love / like + noun", meaning: "Positive feelings.", note: "I like your bag."),
                            TargetExpression(text: "love / like + -ing", meaning: "Activities.", note: "I love swimming."),
                            TargetExpression(text: "Do you like …?", meaning: "Ask.", note: "Do you like cats?"),
                            TargetExpression(text: "Yes, I do / No, I don't", meaning: "Short answers.", note: "Repeat do."),
