                            TargetExpression(text: "Let's + verb + time/place", meaning: "Confirm.", note: "Let's meet at seven."),
                            TargetExpression(text: "at + time, at/in + place", meaning: "The details.", note: "At eight, at the square."),
                            TargetExpression(text: "Sorry, I can't. …?", meaning: "Decline + retry.", note: "…How about Sunday?"),
