                            Exercise(id: "en-foundations-meals-cooking-e2", kind: "gap", prompt: "We ___ flour. Can you buy some?", options: [], answers: ["need"], explain: "need + ingredient."),
                            Exercise(id: "en-foundations-meals-cooking-e3", kind: "order", prompt: "Give a cooking instruction.", options: [], answers: ["Bake it for thirty minutes"], explain: "bake for + duration."),
