                            Exercise(id: "en-foundations-compare-comparatives-e2", kind: "gap", prompt: "My city is ___ (big) than yours.", options: [], answers: ["bigger"], explain: "big → bigger: double the g."),
                            Exercise(id: "en-foundations-compare-comparatives-e3", kind: "order", prompt: "Say the train is faster.", options: [], answers: ["The train is faster than the bus"], explain: "comparative + than."),
                            Exercise(id: "en-foundations-compare-comparatives-e4", kind: "written", prompt: "Fix the mistake: “This film is more good than the book.”", options: [], answers: ["this film is better than the book"], explain: "good → better — the irregular wins.")], skills: ["grammar:comparatives", "grammar:articles", "function:express-opinion", "speaking:justify-opinion"], canDo: ["express-opinion"], prerequisites: ["grammar:articles", "grammar:verb-be"]),
            Lesson(id: "en-foundations-compare-superlatives", title: "Superlatives", goal: "Say which one is the most / the -est in a group.",
                intro: LessonIntro(explanation: [
                            "Short adjectives: the + -est: the cheapest, the biggest, the busiest. Long adjectives: the most + adjective: the most beautiful.",
                            "Superlatives live with in or of: “the cheapest café in town”, “the best day of the year”.",
                            "Irregulars: good → the best, bad → the worst."], examples: [
                            ExampleLine(text: "It's the cheapest café in town.", meaning: "the + -est + in + place."),
                            ExampleLine(text: "That's the most beautiful street here.", meaning: "the most + long adjective."),
                            ExampleLine(text: "August is the busiest month.", meaning: "busy → the busiest."),
                            ExampleLine(text: "This is the best pizza in the city!", meaning: "Irregular: the best."),
                            ExampleLine(text: "Monday was the worst day of the week.", meaning: "the worst + of + group."),
                            ExampleLine(text: "It's the oldest building in the neighbourhood.", meaning: "old → the oldest.")]),
                expressions: [
                            TargetExpression(text: "the … -est in/of …", meaning: "Top of a short-adjective group.", note: "the oldest in the family."),
                            TargetExpression(text: "the most … in/of …", meaning: "Top of a long-adjective group.", note: "the most famous in Spain."),
                            TargetExpression(text: "the best / the worst", meaning: "The two irregular tops.", note: "the best day ever."),
                            TargetExpression(text: "my favourite …", meaning: "Your personal top one.", note: "my favourite café in town."),
                            TargetExpression(text: "What's the best … ?", meaning: "Ask for a recommendation.", note: "What's the best way to get there?"),
                            TargetExpression(text: "one of the … -est", meaning: "Near the top, not the very top.", note: "one of the oldest bars in Madrid.")],
                situation: "A tourist asks you about your town: recommend the best café, the most beautiful square and the worst time to visit.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Recommend the cheapest restaurant you know.", expected: ["<Name> is the cheapest restaurant in town.", "The cheapest restaurant is <Name>."], focus: "the + -est", watch: "Superlatives need the: “the cheapest”, never just “cheapest”."),
                                PracticeQuestion(prompt: "Describe a very famous place in your country. (long adjective)", expected: ["It's one of the most famous places in <country>."], focus: "the most + long adjective", watch: "“the famousest” doesn't exist — the most famous."),
                                PracticeQuestion(prompt: "Which is correct: “the best” or “the most good”?", expected: ["the best"], focus: "irregular superlative", watch: "good → the best, bad → the worst."),
                                PracticeQuestion(prompt: "Ask for the best way to get to the airport.", expected: ["What's the best way to get to the airport?"], focus: "asking for a recommendation", watch: "Fixed question: “What's the best way to …?”"),
                                PracticeQuestion(prompt: "Say your favourite day of the week and why.", expected: ["My favourite day is <day> because …"], focus: "favourite + because", watch: "favourite already means “the one I like most”."),
                                PracticeQuestion(prompt: "Complete: “This is one of ___ (old) bars in the city.”", expected: ["one of the oldest bars in the city"], focus: "one of the -est", watch: "one of + the + superlative + plural noun.")]),
                exercises: [
                            Exercise(id: "en-foundations-compare-superlatives-e1", kind: "choice", prompt: "This is ___ café in the neighbourhood.", options: ["the most popular", "the popularest", "more popular", "popular"], answers: ["the most popular"], explain: "Long adjectives: the most + adjective."),
                            Exercise(id: "en-foundations-compare-superlatives-e2", kind: "gap", prompt: "August is ___ (busy) month here.", options: [], answers: ["the busiest"], explain: "busy → the busiest."),
                            Exercise(id: "en-foundations-compare-superlatives-e3", kind: "order", prompt: "Recommend the best pizza.", options: [], answers: ["This is the best pizza in the city"], explain: "the best + noun + in + place."),
                            Exercise(id: "en-foundations-compare-superlatives-e4", kind: "written", prompt: "Fix: “It's most old building in town.”", options: [], answers: ["it's the oldest building in town"], explain: "old → the oldest, and superlatives need the.")], skills: ["grammar:superlatives", "grammar:comparatives", "function:express-opinion", "vocab:town"], canDo: ["express-opinion"], prerequisites: ["grammar:comparatives"]),
            Lesson(id: "en-foundations-compare-object-pronouns", title: "Object pronouns", goal: "Use me, you, him, her, it, us and them after verbs and prepositions.",
                intro: LessonIntro(explanation: [
                            "After a verb, use the object pronoun: “Can you help me?” “I saw her yesterday.” “Call them later.”",
                            "After prepositions too: “with me”, “for him”, “without them”, “between us”.",
                            "it stays it; you stays you. Subject does the action, object receives it: “She loves him.”"], examples: [
                            ExampleLine(text: "Can you help me?", meaning: "object after a verb."),
                            ExampleLine(text: "I saw them at the market.", meaning: "them = they."),
                            ExampleLine(text: "This gift is for her.", meaning: "object after a preposition."),
                            ExampleLine(text: "Come with us!", meaning: "us = we as object."),
                            ExampleLine(text: "I'll call him tomorrow.", meaning: "him = he as object."),
                            ExampleLine(text: "She works with me.", meaning: "me = I as object.")]),
                expressions: [
                            TargetExpression(text: "verb + me/him/her/them/us", meaning: "The receiver of the action.", note: "Call me. Help us."),
                            TargetExpression(text: "preposition + object pronoun", meaning: "with me, for him, to her.", note: "Never “with I”."),
                            TargetExpression(text: "Let me …", meaning: "Offer or ask permission.", note: "Let me help you."),
                            TargetExpression(text: "between us", meaning: "A secret or shared thing.", note: "Between you and me — never “between you and I”."),
                            TargetExpression(text: "I don't understand it.", meaning: "it for things and ideas.", note: "it = this/that idea."),
