                exercises: [
                            Exercise(id: "en-foundations-compare-object-pronouns-e1", kind: "choice", prompt: "Can you help ___? I can't lift this.", options: ["me", "I", "my", "mine"], answers: ["me"], explain: "After the verb, object pronoun: help me."),
                            Exercise(id: "en-foundations-compare-object-pronouns-e2", kind: "gap", prompt: "This present is for ___. (Anna)", options: [], answers: ["her"], explain: "Anna → her after a preposition."),
                            Exercise(id: "en-foundations-compare-object-pronouns-e3", kind: "order", prompt: "Ask a friend to come along.", options: [], answers: ["Come with us"], explain: "preposition + us."),
                            Exercise(id: "en-foundations-compare-object-pronouns-e4", kind: "written", prompt: "Fix: “She loves he.”", options: [], answers: ["she loves him"], explain: "he is the subject; the object is him.")], skills: ["grammar:object-pronouns", "grammar:subject-pronouns", "function:make-requests"], prerequisites: ["grammar:subject-pronouns"])])
