public enum EnFoundationsPlans {
    public static let unit: CourseUnit = CourseUnit(id: "en-foundations-plans", title: "Plans & advice", subtitle: "What's next", level: "A2", themes: [
                    ConversationTheme("weekend-trip", "The weekend trip", "What are you going to do?", "map", "Course", "You are planning a weekend trip together: say your plans, compare ideas and agree on a route.", 0),
                    ConversationTheme("new-job-jitters", "The new job", "Rules and advice", "briefcase", "Course", "A friend starts a new job tomorrow. Talk about the rules (must, have to) and give friendly advice (should).", 1)], lessons: [
            Lesson(id: "en-foundations-plans-going-to", title: "Going to: plans", goal: "Talk about future plans and intentions with am/is/are going to.",
                intro: LessonIntro(explanation: [
                            "Plans use be + going to + verb: “I'm going to visit my family. She's going to study tonight. We're going to move house.”",
                            "Questions flip be: “Are you going to come?” Negatives add not: “I'm not going to work on Saturday.”",
                            "going to is about intention — a plan already in your head. Time markers: tonight, tomorrow, next week, this weekend."], examples: [
                            ExampleLine(text: "I'm going to learn to cook.", meaning: "An intention."),
                            ExampleLine(text: "She's going to start a new job.", meaning: "Her plan for the future."),
                            ExampleLine(text: "We're going to travel in June.", meaning: "A plan with a date."),
                            ExampleLine(text: "Are you going to watch the match?", meaning: "Ask about a plan."),
                            ExampleLine(text: "I'm not going to pay for that!", meaning: "A refused plan."),
                            ExampleLine(text: "It's going to rain tonight.", meaning: "A prediction with evidence — the clouds!")]),
                expressions: [
                            TargetExpression(text: "I'm going to + verb", meaning: "Your plan.", note: "I'm going to start running."),
                            TargetExpression(text: "Are you going to …?", meaning: "Ask about plans.", note: "Are you going to join us?"),
                            TargetExpression(text: "I'm not going to …", meaning: "A plan you refuse.", note: "I'm not going to stay late."),
                            TargetExpression(text: "What are you going to do …?", meaning: "The classic plan question.", note: "… this weekend?"),
                            TargetExpression(text: "It's going to …", meaning: "Prediction with evidence.", note: "Look at those clouds!"),
                            TargetExpression(text: "next week / this weekend / tonight", meaning: "Anchor the plan in time.", note: "going to + time marker.")],
                situation: "You and a friend plan a free Saturday: say what you're going to do, ask about their plans and find something to do together.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Ask your friend about their plans for the weekend.", expected: ["What are you going to do at the weekend?", "What are you going to do this weekend?"], focus: "the plan question", watch: "“What you going to do?” — the are is obligatory in careful English."),
                                PracticeQuestion(prompt: "Say one plan you have for next month.", expected: ["I'm going to <verb> next month.", "Next month I'm going to <verb>."], focus: "I'm going to", watch: "“I going to travel” — be comes first: “I'm going to”."),
                                PracticeQuestion(prompt: "The sky is very grey. What do you say? (rain)", expected: ["It's going to rain."], focus: "prediction with evidence", watch: "Present evidence → going to: “It's going to rain”."),
                                PracticeQuestion(prompt: "Refuse politely: your friends want to stay out until 2am.", expected: ["I'm not going to stay out that late.", "I'm not going to stay until two."], focus: "negative plan", watch: "“I not going” — “I'm not going to”."),
                                PracticeQuestion(prompt: "Ask if she is going to join the gym with you.", expected: ["Are you going to join the gym with me?"], focus: "are + going to", watch: "Questions flip be: “Are you going to…?”"),
                                PracticeQuestion(prompt: "Say your plans after this course. (two sentences)", expected: ["I'm going to <activity> and I'm going to <activity>."], focus: "chaining plans", watch: "and joins two plans: “I'm going to practise and travel”.")]),
                exercises: [
                            Exercise(id: "en-foundations-plans-going-to-e1", kind: "choice", prompt: "They ___ going to move to Lisbon.", options: ["are", "is", "do", "will"], answers: ["are"], explain: "With they: are going to."),
                            Exercise(id: "en-foundations-plans-going-to-e2", kind: "gap", prompt: "I ___ ___ ___ study tonight. (3 words: intention of I)", options: [], answers: ["am going to", "'m going to"], explain: "I am going to + verb."),
                            Exercise(id: "en-foundations-plans-going-to-e3", kind: "order", prompt: "Ask about their evening plans.", options: [], answers: ["What are you going to do tonight"], explain: "Question word + are + you + going to."),
                            Exercise(id: "en-foundations-plans-going-to-e4", kind: "written", prompt: "Fix: “She going to start a course.”", options: [], answers: ["she's going to start a course", "she is going to start a course"], explain: "She's going to — be is obligatory.")], skills: ["grammar:going-to", "function:make-future-plans", "speaking:describe-routine"], canDo: ["make-future-plans"], prerequisites: ["grammar:verb-be"]),
            Lesson(id: "en-foundations-plans-past-irregular", title: "Irregular past verbs", goal: "Tell past stories with the most common irregular verbs.",
                intro: LessonIntro(explanation: [
                            "Many common verbs are irregular: go → went, see → saw, make → made, take → took, come → came, get → got.",
                            "Negatives and questions return to the base form with did: “I didn't go. Did you see it?” The past lives only in the positive.",
                            "Learn them in pairs: buy → bought, eat → ate, drink → drank, write → wrote, drive → drove, sleep → slept."], examples: [
                            ExampleLine(text: "We went to the coast last summer.", meaning: "go → went."),
                            ExampleLine(text: "I saw your brother yesterday.", meaning: "see → saw."),
                            ExampleLine(text: "She made a cake for my birthday.", meaning: "make → made."),
                            ExampleLine(text: "I didn't take the umbrella.", meaning: "didn't + base form."),
                            ExampleLine(text: "Did you eat anything?", meaning: "did + base form in questions."),
                            ExampleLine(text: "He came home late and went to bed.", meaning: "Two irregulars in one story.")]),
                expressions: [
                            TargetExpression(text: "go → went", meaning: "The most common of all.", note: "We went home early."),
                            TargetExpression(text: "see → saw / take → took", meaning: "Everyday irregulars.", note: "I saw it, I took it."),
                            TargetExpression(text: "make → made / come → came", meaning: "Story verbs.", note: "She made dinner; he came late."),
                            TargetExpression(text: "didn't + base form", meaning: "Past negative.", note: "I didn't sleep well — not “didn't slept”."),
                            TargetExpression(text: "Did you …?", meaning: "Past question.", note: "Did you get my message?"),
                            TargetExpression(text: "yesterday / last night / ago", meaning: "Anchor the story.", note: "two weeks ago.")],
                situation: "You tell a friend about a disastrous day trip: what went wrong, what you saw, what you lost — all in the past.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Say where you went last weekend. (past, place)", expected: ["I went to <place> last weekend."], focus: "went", watch: "“I goed / I wented” — the irregular is went."),
                                PracticeQuestion(prompt: "Say you didn't sleep well last night.", expected: ["I didn't sleep well last night."], focus: "didn't + base", watch: "“didn't slept” — after didn't, the verb is bare: sleep."),
                                PracticeQuestion(prompt: "Ask if your friend saw the news yesterday.", expected: ["Did you see the news yesterday?"], focus: "did + see", watch: "“Did you saw” — after did, base form: see."),
                                PracticeQuestion(prompt: "Tell one thing you made this week. (make)", expected: ["I made <thing> this week."], focus: "made", watch: "make → made, no -ed."),
                                PracticeQuestion(prompt: "Say you came home late yesterday.", expected: ["I came home late yesterday."], focus: "came", watch: "come → came: “I come home late” is present."),
                                PracticeQuestion(prompt: "Tell a mini story: where you went, what you saw, what you bought.", expected: ["I went to <place>, saw <thing> and bought <thing>."], focus: "three irregulars", watch: "One past story, three irregular verbs: went, saw, bought.")]),
                exercises: [
                            Exercise(id: "en-foundations-plans-past-irregular-e1", kind: "choice", prompt: "Yesterday we ___ to the market.", options: ["went", "goed", "go", "gone"], answers: ["went"], explain: "go → went."),
                            Exercise(id: "en-foundations-plans-past-irregular-e2", kind: "gap", prompt: "I ___ your keys on the table. (see, yesterday)", options: [], answers: ["saw"], explain: "see → saw."),
                            Exercise(id: "en-foundations-plans-past-irregular-e3", kind: "order", prompt: "Ask about their dinner.", options: [], answers: ["Did you eat anything"], explain: "Did + you + base verb."),
                            Exercise(id: "en-foundations-plans-past-irregular-e4", kind: "written", prompt: "Fix: “I didn't took the bus.”", options: [], answers: ["i didn't take the bus"], explain: "After didn't: take, never took.")], skills: ["grammar:past-simple-irregular", "function:describe-past-events", "function:tell-a-story"], canDo: ["describe-past-events"], prerequisites: ["grammar:past-simple-regular"]),
            Lesson(id: "en-foundations-plans-modals", title: "Advice & obligation", goal: "Give advice with should and talk about rules with must and have to.",
                intro: LessonIntro(explanation: [
                            "should = good idea, advice: “You should rest. You shouldn't work tonight.” It never takes -s or to.",
                            "must = obligation from the speaker; have to = obligation from outside (rules, timetables): “I must finish this.” “I have to wear a uniform.”",
                            "Questions: “Should I call him?” “Do you have to work on Sundays?” Negatives: “You shouldn't smoke.” “I don't have to get up early.”"], examples: [
                            ExampleLine(text: "You should drink more water.", meaning: "Friendly advice."),
                            ExampleLine(text: "You shouldn't eat so late.", meaning: "Negative advice."),
                            ExampleLine(text: "I must finish this today.", meaning: "The speaker's own obligation."),
                            ExampleLine(text: "She has to wear a uniform.", meaning: "An outside rule."),
                            ExampleLine(text: "Do we have to book a table?", meaning: "Ask about a rule."),
                            ExampleLine(text: "You don't have to come.", meaning: "No obligation — it's optional.")]),
                expressions: [
                            TargetExpression(text: "You should + verb", meaning: "Advice.", note: "You should try it."),
                            TargetExpression(text: "You shouldn't + verb", meaning: "Advice against.", note: "You shouldn't worry."),
                            TargetExpression(text: "I must + verb", meaning: "Strong personal obligation.", note: "I must go now."),
                            TargetExpression(text: "have to + verb", meaning: "Outside rules.", note: "I have to work on Saturdays."),
                            TargetExpression(text: "don't have to", meaning: "No obligation — free choice.", note: "≠ mustn't! don't have to = optional."),
                            TargetExpression(text: "Should I …?", meaning: "Ask for advice.", note: "Should I bring anything?")],
                situation: "A friend starts a new job tomorrow: give advice (should), tell them the rules of your office (have to) and say what is optional (don't have to).",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Your friend has an interview tomorrow. Give one piece of advice.", expected: ["You should sleep early.", "You should arrive early.", "You should prepare some questions."], focus: "should + verb", watch: "“You should to prepare” — no to after should."),
                                PracticeQuestion(prompt: "Say one rule at your work. (have to)", expected: ["I have to <rule>.", "We have to <rule>."], focus: "have to", watch: "“I have to working” — have to + base verb."),
                                PracticeQuestion(prompt: "Advise your friend NOT to check the phone all night.", expected: ["You shouldn't check your phone all night."], focus: "shouldn't", watch: "“You don't should” — the negative is shouldn't."),
                                PracticeQuestion(prompt: "Say Sunday work is optional at your job.", expected: ["I don't have to work on Sundays.", "We don't have to work on Sundays."], focus: "don't have to", watch: "don't have to = optional; mustn't = prohibited!"),
                                PracticeQuestion(prompt: "Ask if you need to bring anything to the party. (should)", expected: ["Should I bring anything?"], focus: "should question", watch: "“Do I should bring?” — should asks directly: “Should I…?”"),
                                PracticeQuestion(prompt: "The doctor says it's necessary: take the medicine every day. (must)", expected: ["I must take the medicine every day.", "You must take the medicine every day."], focus: "must", watch: "must + base verb, no -s, no to.")]),
                exercises: [
                            Exercise(id: "en-foundations-plans-modals-e1", kind: "choice", prompt: "You look tired. You ___ go to bed early.", options: ["should", "should to", "are should", "will should"], answers: ["should"], explain: "should + base verb — advice."),
                            Exercise(id: "en-foundations-plans-modals-e2", kind: "gap", prompt: "At our office we have ___ wear a badge.", options: [], answers: ["to"], explain: "have to + base verb for outside rules."),
                            Exercise(id: "en-foundations-plans-modals-e3", kind: "order", prompt: "Tell your friend the visit is optional.", options: [], answers: ["You don't have to come"], explain: "don't have to = no obligation."),
                            Exercise(id: "en-foundations-plans-modals-e4", kind: "written", prompt: "Fix: “You shoulds rest.”", options: [], answers: ["you should rest"], explain: "Modal verbs never take -s.")], skills: ["grammar:modal-should", "grammar:modal-must-have-to", "function:solve-problems", "vocab:work"], canDo: ["solve-everyday-problems"], prerequisites: ["grammar:present-simple"])])
}

public enum EnFoundationsStay {
    public static let unit: CourseUnit = CourseUnit(id: "en-foundations-stay", title: "Staying somewhere", subtitle: "How much, how many, a room", level: "A2", themes: [
                    ConversationTheme("guest-room", "The guest room", "How much space?", "bed.double", "Course", "Family is visiting. Count the beds, the towels and the problems — is there enough room for everyone?", 0),
                    ConversationTheme("booking-call", "The booking call", "A room for two nights", "phone", "Course", "You book accommodation by phone: dates, price, breakfast — and one special request.", 1)], lessons: [
            Lesson(id: "en-foundations-stay-quantifiers", title: "How much / how many", goal: "Ask about countable and uncountable things with how much and how many.",
                intro: LessonIntro(explanation: [
                            "Countable things (bottles, rooms, tickets) take many: “How many rooms do you need?” Uncountable stuff (water, money, time) takes much: “How much water do you need?”",
                            "In everyday questions, much alone sounds formal: “How much money?” is fine, but people say “How much is it?” — the full countable question needs many.",
                            "Answers use a lot of / some / a few (countable) / a little (uncountable): “We need a few chairs and a little luck.”"], examples: [
                            ExampleLine(text: "How many guests are coming?", meaning: "Countable: guests."),
                            ExampleLine(text: "How much milk is in the fridge?", meaning: "Uncountable: milk."),
                            ExampleLine(text: "How much does it cost?", meaning: "Price always takes much."),
                            ExampleLine(text: "We need a few more chairs.", meaning: "a few + countable."),
                            ExampleLine(text: "There's a little time left.", meaning: "a little + uncountable."),
                            ExampleLine(text: "A lot of people are coming.", meaning: "a lot of works with both.")]),
                expressions: [
                            TargetExpression(text: "How many + plural?", meaning: "Count the things.", note: "How many nights?"),
                            TargetExpression(text: "How much + uncountable?", meaning: "Measure the stuff.", note: "How much luggage?"),
                            TargetExpression(text: "How much is/are …?", meaning: "Ask any price.", note: "How much are the towels?"),
                            TargetExpression(text: "a few + plural", meaning: "A small number.", note: "a few days = algunos días."),
                            TargetExpression(text: "a little + uncountable", meaning: "A small amount.", note: "a little sugar."),
                            TargetExpression(text: "a lot of + both", meaning: "A big amount, always right.", note: "a lot of rooms, a lot of water.")],
                situation: "Family arrives on Friday: count the beds, towels and chairs, check the milk and sugar for coffee, and decide what to buy.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Ask about the number of guests.", expected: ["How many guests are coming?"], focus: "how many", watch: "“How much guests” — people are countable: how many."),
                                PracticeQuestion(prompt: "Ask about the amount of milk in the fridge.", expected: ["How much milk is there?", "How much milk is in the fridge?"], focus: "how much", watch: "milk is uncountable: how much, never how many."),
                                PracticeQuestion(prompt: "Ask the price of the towels.", expected: ["How much are the towels?"], focus: "price", watch: "Price always takes much, even with plural things."),
                                PracticeQuestion(prompt: "Say you need a small number of chairs. (a few)", expected: ["We need a few more chairs.", "I need a few chairs."], focus: "a few", watch: "a few + plural: “a few chairs”, never “a little chairs”."),
                                PracticeQuestion(prompt: "Say there is a small amount of time left.", expected: ["There's a little time left.", "There is a little time left."], focus: "a little", watch: "a little + uncountable: time, money, luck."),
                                PracticeQuestion(prompt: "Safe answer for both: many rooms, much water.", expected: ["We need a lot of rooms and a lot of water."], focus: "a lot of", watch: "When unsure, a lot of works with countable and uncountable.")]),
                exercises: [
                            Exercise(id: "en-foundations-stay-quantifiers-e1", kind: "choice", prompt: "___ many nights are you staying?", options: ["How", "What", "How much", "Which"], answers: ["How"], explain: "nights are countable: How many."),
                            Exercise(id: "en-foundations-stay-quantifiers-e2", kind: "gap", prompt: "There's ___ ___ sugar left. (small amount, uncountable)", options: [], answers: ["a little"], explain: "a little + uncountable."),
                            Exercise(id: "en-foundations-stay-quantifiers-e3", kind: "order", prompt: "Ask about the price of the room.", options: [], answers: ["How much is the room"], explain: "Price: How much is…?"),
                            Exercise(id: "en-foundations-stay-quantifiers-e4", kind: "written", prompt: "Fix: “How much rooms do you need?”", options: [], answers: ["how many rooms do you need"], explain: "rooms are countable: how many.")], skills: ["grammar:quantities", "grammar:countable-uncountable", "grammar:some-any", "vocab:home"], canDo: ["describe-home"], prerequisites: ["grammar:some-any", "grammar:countable-uncountable"]),
            Lesson(id: "en-foundations-stay-accommodation", title: "A room for two nights", goal: "Book accommodation: dates, price, breakfast and one special request.",
                intro: LessonIntro(explanation: [
                            "Booking by phone has a shape: “I'd like to book a room, please.” → dates → “How much is it per night?” → “Does it include breakfast?”",
                            "Room words: a single room (one bed), a double room (big bed), twins (two beds). Say the nights: “from Friday to Sunday — two nights.”",
                            "Special requests stay polite: “Would it be possible to have a quiet room?” The answer you want: “No problem.”"], examples: [
                            ExampleLine(text: "I'd like to book a double room, please.", meaning: "The opening line."),
                            ExampleLine(text: "From Friday to Sunday — two nights.", meaning: "The dates."),
                            ExampleLine(text: "How much is it per night?", meaning: "Price per night."),
                            ExampleLine(text: "Does it include breakfast?", meaning: "The classic question."),
                            ExampleLine(text: "Is there Wi-Fi in the rooms?", meaning: "Check the extras."),
                            ExampleLine(text: "Would it be possible to have a quiet room?", meaning: "The polite special request.")]),
                expressions: [
                            TargetExpression(text: "I'd like to book …", meaning: "Open any booking.", note: "I'd like to = polite want."),
                            TargetExpression(text: "a single / double / twin room", meaning: "Room types.", note: "twin = two separate beds."),
                            TargetExpression(text: "from … to …, … nights", meaning: "Say the dates.", note: "from Friday to Sunday."),
                            TargetExpression(text: "per night", meaning: "Price unit.", note: "€60 per night."),
                            TargetExpression(text: "Does it include breakfast?", meaning: "What's included.", note: "include = venir con."),
                            TargetExpression(text: "Would it be possible to …?", meaning: "Special request.", note: "The politest way to ask.")],
                situation: "You call a small hotel for a weekend: book a double room, ask the price, check breakfast and Wi-Fi, and request a quiet room at the back.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Open the call: you want a double room.", expected: ["I'd like to book a double room, please."], focus: "the opening", watch: "“I want to book a room” works; “I'd like to” sounds friendlier."),
                                PracticeQuestion(prompt: "Say the dates: Friday to Sunday.", expected: ["From Friday to Sunday — two nights."], focus: "dates", watch: "Say the number of nights so the price is clear."),
                                PracticeQuestion(prompt: "Ask the price per night.", expected: ["How much is it per night?"], focus: "per night", watch: "“for a night” also works; per night is the standard."),
                                PracticeQuestion(prompt: "Ask if breakfast comes with the room.", expected: ["Does it include breakfast?", "Is breakfast included?"], focus: "what's included", watch: "Both forms are common — pick one and keep it."),
                                PracticeQuestion(prompt: "Ask about Wi-Fi in the rooms.", expected: ["Is there Wi-Fi in the rooms?"], focus: "the extras", watch: "Wi-Fi is uncountable: Is there, not Are there."),
                                PracticeQuestion(prompt: "Make a special request: a quiet room.", expected: ["Would it be possible to have a quiet room?"], focus: "special requests", watch: "Would it be possible beats “give me a quiet room”.")]),
                exercises: [
                            Exercise(id: "en-foundations-stay-accommodation-e1", kind: "choice", prompt: "I'd like ___ book a twin room.", options: ["to", "for", "that", "book"], answers: ["to"], explain: "I'd like to + verb: I'd like to book."),
                            Exercise(id: "en-foundations-stay-accommodation-e2", kind: "gap", prompt: "How much is it ___ night?", options: [], answers: ["per", "for"], explain: "per night / for a night — price units."),
                            Exercise(id: "en-foundations-stay-accommodation-e3", kind: "order", prompt: "Ask about breakfast.", options: [], answers: ["Does it include breakfast"], explain: "Does + it + include."),
                            Exercise(id: "en-foundations-stay-accommodation-e4", kind: "written", prompt: "Make the special request politely: a room on a high floor.", options: [], answers: ["would it be possible to have a room on a high floor", "could i have a room on a high floor please"], explain: "Would it be possible to have…?")], skills: ["vocab:travel", "function:solve-problems", "grammar:quantities", "vocab:social-expressions"], canDo: ["solve-everyday-problems", "use-transport"], prerequisites: ["grammar:quantities"]),
            Lesson(id: "en-foundations-stay-messages", title: "Sending messages", goal: "Write short informal messages: plans, apologies and quick questions.",
                intro: LessonIntro(explanation: [
                            "Messages drop the formal bits: “Running late — 10 mins!” No “Dear”, no full sentences every time. But clarity stays: who, what, when.",
                            "Useful message chunks: “On my way!” “Are we still on for…?” “Can we move it to…?” “Sorry, something came up.”",
                            "Emoji-free writing still matters: punctuation carries tone. “Fine.” sounds angry; “Fine :)” sounds fine."], examples: [
                            ExampleLine(text: "On my way! 5 mins.", meaning: "The classic delay message."),
                            ExampleLine(text: "Are we still on for Saturday?", meaning: "Confirm a plan."),
                            ExampleLine(text: "Can we move dinner to 9?", meaning: "Change of plan."),
                            ExampleLine(text: "Sorry, something came up at work.", meaning: "The polite cancellation."),
                            ExampleLine(text: "Let me know when you're free.", meaning: "Open-ended plan."),
                            ExampleLine(text: "Got it, thanks!", meaning: "Close the thread.")]),
                expressions: [
                            TargetExpression(text: "On my way!", meaning: "You have left.", note: "Short for I'm on my way."),
                            TargetExpression(text: "Are we still on for …?", meaning: "Confirm the plan.", note: "on for + day/time."),
                            TargetExpression(text: "Can we move it to …?", meaning: "Propose a new time.", note: "move it to + time."),
                            TargetExpression(text: "Something came up.", meaning: "Something happened.", note: "The universal excuse."),
                            TargetExpression(text: "Let me know when …", meaning: "Leave the ball with them.", note: "…you're free / you arrive."),
                            TargetExpression(text: "Got it, thanks!", meaning: "Acknowledge and close.", note: "got it = understood.")],
                situation: "A dinner with friends is in chaos: confirm who's coming, move the time, apologise for a late change and close the chat kindly.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "You left home. Send the classic message.", expected: ["On my way!", "I'm on my way!"], focus: "on my way", watch: "“I'm arriving” sounds like a flight announcement — “On my way!” is the chunk."),
                                PracticeQuestion(prompt: "Check if Saturday dinner is still happening.", expected: ["Are we still on for Saturday?"], focus: "still on", watch: "“Are we still …?” + on for + the plan."),
                                PracticeQuestion(prompt: "Propose moving dinner to nine.", expected: ["Can we move dinner to 9?", "Can we move it to nine?"], focus: "moving plans", watch: "move it to + time — not “move it at nine”."),
                                PracticeQuestion(prompt: "Cancel politely: work happened.", expected: ["Sorry, something came up at work.", "Sorry — something came up."], focus: "polite cancellation", watch: "something came up explains without details."),
                                PracticeQuestion(prompt: "Leave the decision to your friend.", expected: ["Let me know when you're free."], focus: "open-ended", watch: "let me know + when + present: when you're free."),
                                PracticeQuestion(prompt: "Close the conversation after the plan is set.", expected: ["Got it, thanks!", "Perfect, see you then!"], focus: "closing", watch: "Every message thread needs a friendly full stop.")]),
                exercises: [
                            Exercise(id: "en-foundations-stay-messages-e1", kind: "choice", prompt: "___ we still on for tonight?", options: ["Are", "Is", "Do", "Will"], answers: ["Are"], explain: "we + are: Are we still on for…?"),
                            Exercise(id: "en-foundations-stay-messages-e2", kind: "gap", prompt: "Sorry, something ___ ___ at work. (happened, 2 words)", options: [], answers: ["came up"], explain: "something came up = surgió algo."),
                            Exercise(id: "en-foundations-stay-messages-e3", kind: "order", prompt: "Propose a new time. (dinner / can / move / we / to nine)", options: [], answers: ["Can we move dinner to nine"], explain: "Can we move + plan + to + time."),
                            Exercise(id: "en-foundations-stay-messages-e4", kind: "written", prompt: "Close the thread after agreeing on a plan.", options: [], answers: ["got it thanks", "perfect see you then", "great see you then"], explain: "Any friendly closing works.")], skills: ["writing:message", "vocab:social-expressions", "grammar:present-continuous", "function:make-suggestions"], canDo: ["tell-a-story"], prerequisites: ["grammar:present-continuous"])])
}

public enum EnFoundationsHealth {
    public static let unit: CourseUnit = CourseUnit(id: "en-foundations-health", title: "Health & habits", subtitle: "Feeling your best", level: "A2", themes: [
                    ConversationTheme("doctor-visit", "At the doctor's", "Describe the pain", "stethoscope", "Course", "You don't feel well and describe your symptoms to a doctor who asks precise questions.", 0),
                    ConversationTheme("habit-reset", "The habit reset", "Advice for better weeks", "figure.run", "Course", "You and a friend compare tired weeks and give each other friendly advice with should.", 1)], lessons: [
            Lesson(id: "en-foundations-health-symptoms", title: "Describing symptoms", goal: "Explain what hurts and for how long at the doctor's.",
                intro: LessonIntro(explanation: [
                            "Symptoms use have got: “I've got a headache / a sore throat / a temperature.” Pain uses hurt: “My back hurts.”",
                            "Duration with for + present perfect: “I've had this cold for three days.” The doctor asks: “How long have you had it?”",
                            "Severity helps the doctor: “It's a sharp pain.” “It's worse when I move.”"], examples: [
                            ExampleLine(text: "I've got a headache and a temperature.", meaning: "Two symptoms."),
                            ExampleLine(text: "My back hurts when I move.", meaning: "Pain + trigger."),
                            ExampleLine(text: "I've had this cold for three days.", meaning: "Duration with for."),
                            ExampleLine(text: "How long have you had it?", meaning: "The doctor's question."),
                            ExampleLine(text: "It's worse in the morning.", meaning: "When it hurts more."),
                            ExampleLine(text: "I feel dizzy when I stand up.", meaning: "Another symptom."),
                            ExampleLine(text: "I have a pain in my lower back.", meaning: "a pain in + body part.")]),
                expressions: [
                            TargetExpression(text: "I've got a headache / a cold", meaning: "have got + illness.", note: "a + illness: a cold."),
                            TargetExpression(text: "My … hurts", meaning: "Point at the pain.", note: "My throat hurts."),
                            TargetExpression(text: "I've had … for + time", meaning: "Say how long.", note: "for three days."),
                            TargetExpression(text: "How long have you had it?", meaning: "Answer: for + time.", note: "The standard question."),
                            TargetExpression(text: "It's worse when …", meaning: "When it hurts more.", note: "…when I breathe."),
                            TargetExpression(text: "I feel dizzy / sick", meaning: "Other feelings.", note: "dizzy = mareado.")],
                situation: "At the doctor's: describe three symptoms, say how long you've had them, and answer the doctor's follow-up questions precisely.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Say your main symptom: a sore throat.", expected: ["I've got a sore throat."], focus: "have got", watch: "a sore throat — the article matters."),
                                PracticeQuestion(prompt: "Say your back hurts at night.", expected: ["My back hurts at night."], focus: "hurt", watch: "hurts for one body part: my back hurts."),
                                PracticeQuestion(prompt: "Say you've had the cold for a week.", expected: ["I've had this cold for a week."], focus: "for + time", watch: "“I have this cold since Monday” — use have had + for."),
                                PracticeQuestion(prompt: "Answer the doctor: three days.", expected: ["For three days.", "I've had it for three days."], focus: "duration", watch: "for + period: for three days."),
                                PracticeQuestion(prompt: "Say your temperature is high.", expected: ["I've got a temperature.", "I have a temperature."], focus: "temperature", watch: "a temperature — con artículo, siempre.")]),
                exercises: [
                            Exercise(id: "en-foundations-health-symptoms-e1", kind: "choice", prompt: "I've ___ a headache since Monday.", options: ["had", "have", "got has", "having"], answers: ["had"], explain: "have got / have had for symptoms."),
                            Exercise(id: "en-foundations-health-symptoms-e2", kind: "gap", prompt: "My ___ ___ when I walk. (pain in the foot)", options: [], answers: ["foot hurts", "feet hurt"], explain: "body part + hurts."),
                            Exercise(id: "en-foundations-health-symptoms-e3", kind: "order", prompt: "Ask the patient about duration.", options: [], answers: ["How long have you had it"], explain: "How long + have + you + had."),
                            Exercise(id: "en-foundations-health-symptoms-e4", kind: "written", prompt: "Diga cuánto tiempo lleva con el síntoma.", options: [], answers: ["i've had it for two weeks", "for two weeks", "two weeks"], explain: "for + period.")], skills: ["vocab:health", "grammar:have-got", "grammar:present-perfect", "function:talk-about-health"], canDo: ["solve-everyday-problems"], prerequisites: ["grammar:present-perfect"]),
            Lesson(id: "en-foundations-health-advice", title: "Friendly advice", goal: "Give and respond to advice about health and habits with should.",
                intro: LessonIntro(explanation: [
                            "Advice with should: “You should sleep more.” “You shouldn't check your phone in bed.” Never should to.",
                            "Soften advice with maybe and try: “Maybe you should try going to bed earlier.” try + -ing for experiments.",
                            "Accept or decline: “You're right, I'll try.” “I know, I know… it's hard!” Advice between friends is a dance."], examples: [
                            ExampleLine(text: "You should sleep more.", meaning: "The basic advice."),
                            ExampleLine(text: "You shouldn't drink coffee at night.", meaning: "Advice against."),
                            ExampleLine(text: "Maybe you should try walking home.", meaning: "Softer advice."),
                            ExampleLine(text: "You're right, I'll try.", meaning: "Accepting."),
                            ExampleLine(text: "I know, I know… it's hard!", meaning: "Declining honestly."),
                            ExampleLine(text: "Drink some water and see.", meaning: "Simple instructions."),
                            ExampleLine(text: "You should see a doctor if it lasts a week.", meaning: "Advice with a limit.")]),
                expressions: [
                            TargetExpression(text: "You should + verb", meaning: "Friendly advice.", note: "You should rest."),
                            TargetExpression(text: "You shouldn't + verb", meaning: "Advice against.", note: "You shouldn't skip breakfast."),
                            TargetExpression(text: "Maybe you should try + -ing", meaning: "Softer advice.", note: "…try going to bed earlier."),
                            TargetExpression(text: "You're right.", meaning: "Accept advice.", note: "Then: I'll try."),
                            TargetExpression(text: "I'll try.", meaning: "Promise an attempt.", note: "try, not try to definitely."),
                            TargetExpression(text: "See if it helps.", meaning: "Close the advice.", note: "see if + clause.")],
                situation: "A friend has been tired for weeks: hear the symptoms, give three pieces of advice with should and one with try + -ing, and agree on a first step.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Give advice about screens at night. (shouldn't)", expected: ["You shouldn't use screens at night."], focus: "shouldn't", watch: "shouldn't + base verb: no to."),
                                PracticeQuestion(prompt: "Give softer advice: walking after lunch. (try)", expected: ["Maybe you should try walking after lunch."], focus: "try + -ing", watch: "try + -ing for the experiment."),
                                PracticeQuestion(prompt: "Accept the advice.", expected: ["You're right, I'll try."], focus: "accepting", watch: "I'll try — promise an attempt."),
                                PracticeQuestion(prompt: "Close the advice with a check.", expected: ["See if it helps."], focus: "closing", watch: "see if it helps = a ver si funciona."),
                                PracticeQuestion(prompt: "Advise seeing a doctor if the pain continues.", expected: ["You should see a doctor if the pain continues.", "You should see a doctor."], focus: "see a doctor", watch: "see a doctor = visitar al médico; watch no.")]),
                exercises: [
                            Exercise(id: "en-foundations-health-advice-e1", kind: "choice", prompt: "You look tired. You ___ go to bed early.", options: ["should", "should to", "are should", "will should"], answers: ["should"], explain: "should + base verb."),
                            Exercise(id: "en-foundations-health-advice-e2", kind: "gap", prompt: "Maybe you should try ___ before ten. (sleep)", options: [], answers: ["sleeping", "to sleep"], explain: "try + -ing for the experiment."),
                            Exercise(id: "en-foundations-health-advice-e3", kind: "order", prompt: "Advise against coffee at night.", options: [], answers: ["You shouldn't drink coffee at night"], explain: "shouldn't + base verb."),
                            Exercise(id: "en-foundations-health-advice-e4", kind: "written", prompt: "Accept advice and promise an attempt.", options: [], answers: ["you're right i'll try", "youre right i will try"], explain: "You're right, I'll try.")], skills: ["grammar:modal-should", "grammar:gerunds-infinitives", "vocab:health", "function:talk-about-health"], canDo: ["solve-everyday-problems"], prerequisites: ["grammar:modal-should"]),
            Lesson(id: "en-foundations-health-habits", title: "Habits: then and now", goal: "Compare old and new habits with used to and now, and say what changed.",
                intro: LessonIntro(explanation: [
                            "Old habits with used to: “I used to sleep eight hours.” New ones with now + present: “Now I sleep five.” The contrast tells the story.",
                            "Frequency still works: “I hardly ever exercise now.” hardly ever = almost never — softer than never.",
                            "Be honest about difficulty: “It's harder than I thought.” than + the comparison."], examples: [
                            ExampleLine(text: "I used to sleep eight hours.", meaning: "The old habit."),
                            ExampleLine(text: "Now I sleep five.", meaning: "The present reality."),
                            ExampleLine(text: "I hardly ever exercise now.", meaning: "almost never."),
                            ExampleLine(text: "It's harder than I thought.", meaning: "than + comparison."),
                            ExampleLine(text: "I've started walking to work.", meaning: "A new habit: start + -ing."),
                            ExampleLine(text: "My weekends used to be active. Now they're for the sofa.", meaning: "Contrast con humor.")]),
                expressions: [
                            TargetExpression(text: "used to + verb", meaning: "The old you.", note: "I used to run every day."),
                            TargetExpression(text: "now + present", meaning: "The current you.", note: "Now I barely move."),
                            TargetExpression(text: "hardly ever", meaning: "Almost never.", note: "Softer than never."),
                            TargetExpression(text: "… than I thought", meaning: "Reality check.", note: "harder, easier, better."),
                            TargetExpression(text: "I've started + -ing", meaning: "A new habit.", note: "I've started cycling."),
                            TargetExpression(text: "every other day", meaning: "Frequency phrase.", note: "Lunes, miércoles, viernes…")],
                situation: "You compare your student life with your working life: sleep, exercise, food — used to for the past, now for the present, and one new habit you've started.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Say an old exercise habit. (run every day)", expected: ["I used to run every day."], focus: "used to", watch: "used to + base verb."),
                                PracticeQuestion(prompt: "Say the present: no time now.", expected: ["Now I don't have time."], focus: "now", watch: "now + present simple."),
                                PracticeQuestion(prompt: "Say you almost never cook these days.", expected: ["I hardly ever cook these days."], focus: "hardly ever", watch: "hardly ever = casi nunca."),
                                PracticeQuestion(prompt: "Say one new habit you've started. (walking to work)", expected: ["I've started walking to work."], focus: "start + -ing", watch: "I've started + -ing: the new habit."),
                                PracticeQuestion(prompt: "Say your weekends used to be active.", expected: ["My weekends used to be active."], focus: "used to", watch: "used to + verbo base.")]),
                exercises: [
                            Exercise(id: "en-foundations-health-habits-e1", kind: "choice", prompt: "I ___ to run every day when I was a student.", options: ["used", "use", "was use", "am used"], answers: ["used"], explain: "Past habit: used to + verb."),
                            Exercise(id: "en-foundations-health-habits-e2", kind: "gap", prompt: "I ___ ___ ever cook these days. (casi nunca)", options: [], answers: ["hardly ever"], explain: "hardly ever = almost never."),
                            Exercise(id: "en-foundations-health-habits-e3", kind: "order", prompt: "Say your new habit. (started / I've / walking / to work)", options: [], answers: ["I've started walking to work"], explain: "I've started + -ing."),
                            Exercise(id: "en-foundations-health-habits-e4", kind: "written", prompt: "Compare: sleep eight hours before, five now.", options: [], answers: ["i used to sleep eight hours now i sleep five"], explain: "used to … now …")], skills: ["grammar:used-to", "grammar:frequency-adverbs", "grammar:present-perfect", "vocab:health"], canDo: ["solve-everyday-problems"], prerequisites: ["grammar:past-simple-irregular"])])
}

public enum EnFoundationsExperiences {
    public static let unit: CourseUnit = CourseUnit(id: "en-foundations-experiences", title: "Experiences & stories", subtitle: "Have you ever…?", level: "B1", themes: [
                    ConversationTheme("travel-bucket-list", "The bucket list", "Have you ever…?", "airplane", "Course", "You compare life experiences: places you have and haven't been, things you have and haven't tried.", 0),
                    ConversationTheme("story-night", "Story night", "What was happening?", "moon.stars", "Course", "You tell a story with background: what was happening when something unexpected occurred.", 1)], lessons: [
            Lesson(id: "en-foundations-experiences-present-perfect", title: "Present perfect: experiences", goal: "Talk about life experiences with have/has + past participle, without saying when.",
                intro: LessonIntro(explanation: [
                            "Experiences without a time use have/has + past participle: “I've visited Rome. She's never tried sushi. Have you been to Japan?”",
                            "The moment you say WHEN, switch to past simple: “I've been to Rome. I went there in 2019.”",
                            "Participates are irregular often: be → been, see → seen, go → gone/been, eat → eaten, do → done."], examples: [
                            ExampleLine(text: "I've never been to Asia.", meaning: "A life experience (not yet!)."),
                            ExampleLine(text: "Have you ever tried paella?", meaning: "ever = in your life."),
                            ExampleLine(text: "She's seen that film three times.", meaning: "Repeated experience."),
                            ExampleLine(text: "We've just finished dinner.", meaning: "just = a moment ago."),
                            ExampleLine(text: "I've already packed, but I haven't printed the tickets.", meaning: "already / not yet."),
                            ExampleLine(text: "I went to Rome in 2019.", meaning: "WHEN given → past simple.")]),
                expressions: [
                            TargetExpression(text: "I've (never/ever/already) …", meaning: "Experience, no date.", note: "I've never driven a van."),
                            TargetExpression(text: "Have you ever …?", meaning: "The classic experience question.", note: "Reply: Yes, I have / No, I haven't."),
                            TargetExpression(text: "I've just …", meaning: "Very recent.", note: "I've just arrived."),
                            TargetExpression(text: "… twice / three times", meaning: "Count the experience.", note: "I've read it twice."),
                            TargetExpression(text: "gone to vs been to", meaning: "gone = still there; been = visited and returned.", note: "She's gone to Rome (not back yet)."),
                            TargetExpression(text: "When? → past simple", meaning: "The golden switch rule.", note: "I've been to Peru. I went in 2018.")],
                situation: "You meet a traveller at a hostel: swap life experiences with Have you ever…? and ask follow-up questions with past simple when they give a when.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Ask a traveller if they have ever visited Japan.", expected: ["Have you ever been to Japan?", "Have you ever visited Japan?"], focus: "Have you ever…?", watch: "“Did you ever visit…?” is possible in AmE, but “Have you ever…?” is the safest form."),
                                PracticeQuestion(prompt: "Answer negatively: you have never tried surfing.", expected: ["I've never tried surfing.", "I have never tried surfing."], focus: "never + participle", watch: "“I've never tried to surf” changes meaning slightly; keep “tried surfing”."),
                                PracticeQuestion(prompt: "Say you visited Rome in 2019 (mention the year).", expected: ["I went to Rome in 2019."], focus: "when → past simple", watch: "“I've gone to Rome in 2019” — a finished time forbids the present perfect."),
                                PracticeQuestion(prompt: "Your friend is not here — she went to the airport. Say it two ways.", expected: ["She's gone to the airport.", "She has gone to the airport."], focus: "gone to", watch: "“She's been to the airport” means she went and came back."),
                                PracticeQuestion(prompt: "Say you have seen that film three times.", expected: ["I've seen that film three times.", "I have seen that film three times."], focus: "counting experiences", watch: "“I saw it three times” needs a past anchor; without one, prefer the present perfect."),
                                PracticeQuestion(prompt: "Ask a follow-up when someone says “I've been to Iceland”.", expected: ["When did you go?", "What did you see there?", "How was it?"], focus: "switching to past", watch: "The follow-up asks about the trip → past simple.")]),
                exercises: [
                            Exercise(id: "en-foundations-experiences-present-perfect-e1", kind: "choice", prompt: "___ you ever eaten octopus?", options: ["Have", "Did", "Are", "Do"], answers: ["Have"], explain: "Experience question: Have you ever…?"),
                            Exercise(id: "en-foundations-experiences-present-perfect-e2", kind: "gap", prompt: "She's ___ (see) that exhibition twice.", options: [], answers: ["seen"], explain: "see → seen with have/has."),
                            Exercise(id: "en-foundations-experiences-present-perfect-e3", kind: "order", prompt: "Say it is very recent.", options: [], answers: ["I've just arrived"], explain: "have + just + participle."),
                            Exercise(id: "en-foundations-experiences-present-perfect-e4", kind: "written", prompt: "Fix: “I've visited Peru in 2018.”", options: [], answers: ["i visited peru in 2018"], explain: "With a finished time (in 2018), use past simple.")], skills: ["grammar:present-perfect", "grammar:past-simple-irregular", "function:describe-past-events", "listening:inference"], canDo: ["describe-past-events"], prerequisites: ["grammar:past-simple-regular", "grammar:object-pronouns"]),
            Lesson(id: "en-foundations-experiences-past-continuous", title: "Past continuous: background", goal: "Set the scene of a past story with was/were + -ing, and interrupt it with past simple.",
                intro: LessonIntro(explanation: [
                            "Background actions use was/were + -ing: “It was raining. People were running. I was cooking.”",
                            "The classic structure: past continuous (background) + when/until + past simple (event): “I was cooking when the lights went out.”",
                            "Two parallel background actions use while: “While she was sleeping, he was reading.”"], examples: [
                            ExampleLine(text: "The sun was setting and the birds were singing.", meaning: "Scene painting."),
                            ExampleLine(text: "I was cooking when the phone rang.", meaning: "Background + interruption."),
                            ExampleLine(text: "They were waiting for the bus when it started to rain.", meaning: "Longer action + event."),
                            ExampleLine(text: "While we were driving, it snowed.", meaning: "while + two past tenses."),
                            ExampleLine(text: "What were you doing at midnight?", meaning: "Question about a past moment."),
                            ExampleLine(text: "I wasn't listening, sorry.", meaning: "Negative background.")]),
                expressions: [
                            TargetExpression(text: "was/were + -ing", meaning: "The background of the story.", note: "It was getting dark."),
                            TargetExpression(text: "… when + past simple", meaning: "The event that interrupts.", note: "…when he appeared."),
                            TargetExpression(text: "while + was/were -ing", meaning: "Two things at once.", note: "While I was waiting, I read."),
                            TargetExpression(text: "What were you doing…?", meaning: "Ask about a past moment.", note: "…at eight last night?"),
                            TargetExpression(text: "Suddenly, …", meaning: "Move from background to event.", note: "Suddenly, the door opened."),
                            TargetExpression(text: "It was a normal evening when…", meaning: "The classic story opener.", note: "…everything changed.")],
                situation: "You and a friend swap short stories: set the scene with past continuous, then deliver the surprise event with past simple.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Set the scene: the rain / fall, and people / run for shelter.", expected: ["The rain was falling and people were running for shelter."], focus: "was/were + -ing", watch: "“The rain fell” is an event — the background is “was falling”."),
                                PracticeQuestion(prompt: "Add the interruption: you were cooking / lights went out.", expected: ["I was cooking when the lights went out."], focus: "when + past simple", watch: "The short event takes past simple: “went out”, not “was going out”."),
                                PracticeQuestion(prompt: "Ask what your friend was doing at ten last night.", expected: ["What were you doing at ten last night?"], focus: "were + -ing question", watch: "“What did you do at ten?” asks for an answer list; “were doing” asks about the moment."),
                                PracticeQuestion(prompt: "Say two parallel actions: you drove / your partner read the map.", expected: ["While I was driving, my partner was reading the map."], focus: "while + continuous", watch: "Both long actions take the continuous after while."),
                                PracticeQuestion(prompt: "Open a story: normal evening / everything changed.", expected: ["It was a normal evening when everything changed."], focus: "story opener", watch: "Background first (was), event second (changed)."),
                                PracticeQuestion(prompt: "Negative background: you weren't listening when she told you.", expected: ["I wasn't listening when she told me."], focus: "wasn't + -ing", watch: "“I didn't listening” — negatives of the continuous use wasn't/weren't.")]),
                exercises: [
                            Exercise(id: "en-foundations-experiences-past-continuous-e1", kind: "choice", prompt: "I ___ dinner when the doorbell rang.", options: ["was cooking", "cooked", "am cooking", "have cooked"], answers: ["was cooking"], explain: "Background action: was + -ing."),
                            Exercise(id: "en-foundations-experiences-past-continuous-e2", kind: "gap", prompt: "While they ___ ___ (wait), the bus arrived.", options: [], answers: ["were waiting"], explain: "Plural background: were + -ing."),
                            Exercise(id: "en-foundations-experiences-past-continuous-e3", kind: "order", prompt: "Ask about a past moment. (you / at midnight / what / were / doing)", options: [], answers: ["What were you doing at midnight"], explain: "Question word + were + you + -ing."),
                            Exercise(id: "en-foundations-experiences-past-continuous-e4", kind: "written", prompt: "Fix: “While I cooked, she was watching TV.”", options: [], answers: ["while i was cooking she was watching tv"], explain: "Both parallel long actions take the continuous: was cooking.")], skills: ["grammar:past-continuous", "grammar:past-simple-regular", "function:tell-a-story", "speaking:tell-past-story"], canDo: ["tell-a-story"], prerequisites: ["grammar:past-was-were", "grammar:present-continuous"]),
            Lesson(id: "en-foundations-experiences-used-to", title: "Used to: past habits", goal: "Compare the past with now using used to / didn't use to.",
                intro: LessonIntro(explanation: [
                            "Past habits that stopped use used to + verb: “I used to play outside every day. She used to live in Berlin.”",
                            "Negative: didn't use to: “We didn't use to have a car.” Question: “Did you use to…?” Note: no -d in the negative/question.",
                            "For states still true, prefer present simple; for single past events, past simple. used to is for repeated past routines that ended."], examples: [
                            ExampleLine(text: "I used to hate coffee. Now I love it.", meaning: "Past habit, changed."),
                            ExampleLine(text: "There used to be a cinema here.", meaning: "Past state that ended."),
                            ExampleLine(text: "We didn't use to lock the door.", meaning: "Past absence of a habit."),
                            ExampleLine(text: "Did people use to write letters?", meaning: "Question form."),
                            ExampleLine(text: "He didn't use to cook — now he's a chef!", meaning: "Big change."),
                            ExampleLine(text: "I used to walk to school.", meaning: "Routine when you were young.")]),
                expressions: [
                            TargetExpression(text: "used to + verb", meaning: "A past habit that stopped.", note: "I used to smoke."),
                            TargetExpression(text: "didn't use to + verb", meaning: "Something you didn't do before.", note: "No -d after use here."),
                            TargetExpression(text: "Did you use to …?", meaning: "Ask about old habits.", note: "Did you use to play an instrument?"),
                            TargetExpression(text: "… but now …", meaning: "The contrast sentence.", note: "I used to walk, but now I cycle."),
                            TargetExpression(text: "There used to be …", meaning: "Past places and things.", note: "There used to be a lake here."),
                            TargetExpression(text: "be used to + -ing", meaning: "Different! = estar acostumbrado a.", note: "I'm used to getting up early.")],
                situation: "You look at old photos with a friend: compare childhood habits with life now using used to, didn't use to and but now.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Say one childhood habit you have stopped.", expected: ["I used to <habit>."], focus: "used to", watch: "“I used to played” — used to + base verb."),
                                PracticeQuestion(prompt: "Say something about your town that no longer exists. (There used to…)", expected: ["There used to be <place>.", "There used to be a market here."], focus: "There used to be", watch: "“There used to have” is wrong — use be for places/things."),
                                PracticeQuestion(prompt: "Say you didn't like vegetables before.", expected: ["I didn't use to like vegetables.", "I used to not like vegetables."], focus: "didn't use to", watch: "Careful spelling: didn't use to (no -d)."),
                                PracticeQuestion(prompt: "Ask a friend about an old habit. (instrument / sport)", expected: ["Did you use to play an instrument?", "Did you use to do any sport?"], focus: "Did you use to…?", watch: "“Did you used to…?” — in questions, use to loses the -d."),
                                PracticeQuestion(prompt: "Contrast: past walk to school, now cycle.", expected: ["I used to walk to school, but now I cycle."], focus: "but now", watch: "The contrast word now makes the change explicit."),
                                PracticeQuestion(prompt: "Say you are accustomed to early mornings. (be used to)", expected: ["I'm used to getting up early."], focus: "be used to + -ing", watch: "Different structure: be used to + -ing = estar acostumbrado.")]),
                exercises: [
                            Exercise(id: "en-foundations-experiences-used-to-e1", kind: "choice", prompt: "She ___ live in Berlin when she was young.", options: ["used to", "use to", "was used to", "would been"], answers: ["used to"], explain: "Past habit: used to + verb."),
                            Exercise(id: "en-foundations-experiences-used-to-e2", kind: "gap", prompt: "We ___ ___ ___ have a car. (negative, 3 words)", options: [], answers: ["didn't use to", "did not use to"], explain: "didn't use to — no -d."),
                            Exercise(id: "en-foundations-experiences-used-to-e3", kind: "order", prompt: "Ask about old habits. (you / use / play / did / to / an instrument)", options: [], answers: ["Did you use to play an instrument"], explain: "Did + you + use to + base verb."),
                            Exercise(id: "en-foundations-experiences-used-to-e4", kind: "written", prompt: "Fix: “I'm used to get up early.”", options: [], answers: ["i'm used to getting up early", "i am used to getting up early"], explain: "be used to + -ing: getting.")], skills: ["grammar:used-to", "grammar:past-simple-irregular", "function:tell-a-story", "vocab:daily-routine"], canDo: ["tell-a-story"], prerequisites: ["grammar:past-simple-irregular"]),
            Lesson(id: "en-foundations-experiences-story-writing", title: "Writing your story", goal: "Turn an experience into a short written story with a beginning, a turn and an ending.",
                intro: LessonIntro(explanation: [
                            "Written stories breathe: short sentences for tension, long ones for scenery. Start in the middle: “The lock wouldn't turn.”",
                            "Spine: opening moment → the turn (when/until/suddenly) → the ending feeling. Three paragraphs, 80-120 words.",
                            "Show, don't label: not “it was a bad day” but “my keys, my phone and my umbrella were all on the kitchen table — together, at home, where I wasn't.”"], examples: [
                            ExampleLine(text: "The lock wouldn't turn.", meaning: "Open in the middle of the trouble."),
                            ExampleLine(text: "It started fine: sun, coffee, an early train.", meaning: "A calm before."),
                            ExampleLine(text: "Until the announcement, everything was normal.", meaning: "until signals the turn."),
                            ExampleLine(text: "Suddenly, the platform emptied.", meaning: "sudden movement, short sentence."),
                            ExampleLine(text: "By the time I got home, I'd laughed about it twice.", meaning: "Ending with distance."),
                            ExampleLine(text: "Some days you're the tourist, even in your own city.", meaning: "A closing thought.")]),
                expressions: [
                            TargetExpression(text: "Open in the middle", meaning: "First line = trouble or action.", note: "Skip the weather report."),
                            TargetExpression(text: "until / when + the turn", meaning: "Move the plot.", note: "Until the doors closed…"),
                            TargetExpression(text: "Suddenly, + short sentence", meaning: "Pace change.", note: "Short = tense."),
                            TargetExpression(text: "By the time …, …", meaning: "Close with distance.", note: "By the time + past, past perfect feels natural."),
                            TargetExpression(text: "a closing thought", meaning: "One reflective line.", note: "Some days you win, some days you learn."),
                            TargetExpression(text: "80-120 words", meaning: "The short-story sweet spot.", note: "Every sentence earns its place.")],
                situation: "You write a 100-word story for the class blog: a travel day that went wrong — opening in the middle, one turn, one closing thought.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Open your story in the middle of the trouble. (the lock)", expected: ["The lock wouldn't turn."], focus: "the opening", watch: "“Last summer I travelled…” is a report, not a story."),
                                PracticeQuestion(prompt: "Set the calm before: sun, coffee, an early train.", expected: ["It started fine: sun, coffee, an early train."], focus: "the calm", watch: "A calm first line makes the turn hit harder."),
                                PracticeQuestion(prompt: "Signal the turn: the announcement changed everything. (until)", expected: ["Until the announcement, everything was normal."], focus: "until", watch: "until + noun/clause marks the exact turn."),
                                PracticeQuestion(prompt: "Add pace: the platform emptied suddenly. (short sentence)", expected: ["Suddenly, the platform emptied."], focus: "suddenly", watch: "One-word openers (Suddenly, Luckily) control pace."),
                                PracticeQuestion(prompt: "Close with distance and humour.", expected: ["By the time I got home, I'd laughed about it twice."], focus: "the ending", watch: "Distance turns disaster into story."),
                                PracticeQuestion(prompt: "Add a one-line reflection to close.", expected: ["Some days you're the tourist, even in your own city."], focus: "the thought", watch: "One line, not a moral lecture.")]),
                exercises: [
                            Exercise(id: "en-foundations-experiences-story-writing-e1", kind: "choice", prompt: "Which opening starts IN the trouble?", options: ["The lock wouldn't turn.", "Last summer I travelled a lot.", "It was a sunny day in June.", "I want to tell you about trains."], answers: ["The lock wouldn't turn."], explain: "In medias res: start inside the problem."),
                            Exercise(id: "en-foundations-experiences-story-writing-e2", kind: "gap", prompt: "___ the doors closed, we realised the mistake.", options: [], answers: ["when", "until"], explain: "when/until mark the turn."),
                            Exercise(id: "en-foundations-experiences-story-writing-e3", kind: "order", prompt: "Add pace to the escape.", options: [], answers: ["Suddenly the platform emptied"], explain: "Suddenly + short clause."),
                            Exercise(id: "en-foundations-experiences-story-writing-e4", kind: "written", prompt: "Write a one-line closing thought for a travel disaster story.", options: [], answers: ["some days you're the tourist even in your own city", "some days you win some days you learn", "at least i have a story now"], explain: "Reflective, light, one line.")], skills: ["writing:story", "grammar:connectors", "grammar:past-continuous", "function:tell-a-story", "speaking:tell-past-story"], canDo: ["tell-a-story"], prerequisites: ["grammar:past-continuous"])])
}

public enum EnFoundationsConnections {
    public static let unit: CourseUnit = CourseUnit(id: "en-foundations-connections", title: "Opinions & connections", subtitle: "If, which, however", level: "B1", themes: [
                    ConversationTheme("plan-b", "Plan B", "If it rains…", "cloud.bolt", "Course", "Your outdoor plan is at risk. Negotiate conditionals: if this happens, we'll do that.", 0),
                    ConversationTheme("movie-debate", "The film debate", "Which one? However…", "film", "Course", "You review a film together: describe scenes with relative clauses and connect opinions with however and although.", 1)], lessons: [
            Lesson(id: "en-foundations-connections-first-conditional", title: "First conditional", goal: "Talk about real future possibilities with if + present, will + verb.",
                intro: LessonIntro(explanation: [
                            "Real future conditions: “If it rains, we'll stay in.” The if-clause uses present simple; the result uses will.",
                            "Order can flip, but the comma disappears: “We'll stay in if it rains.” Never will inside the if-clause.",
                            "Variations: “If it rains, we might stay in / we can stay in / let's stay in.”"], examples: [
                            ExampleLine(text: "If it rains, we'll stay home.", meaning: "The basic pattern."),
                            ExampleLine(text: "We'll be late if the bus doesn't come.", meaning: "Result first, no comma."),
                            ExampleLine(text: "If you help me, I'll help you.", meaning: "An exchange."),
                            ExampleLine(text: "If they don't hurry, they'll miss the train.", meaning: "Negative in the if-clause."),
                            ExampleLine(text: "If I see him, I might tell him.", meaning: "might = less certain."),
                            ExampleLine(text: "What will you do if it snows?", meaning: "The question form.")]),
                expressions: [
                            TargetExpression(text: "If + present, will + verb", meaning: "Real future possibility.", note: "If it rains, we'll stay in."),
                            TargetExpression(text: "… if + present", meaning: "Result first, no comma.", note: "I'll call you if I'm late."),
                            TargetExpression(text: "If not, … / Otherwise, …", meaning: "The other branch.", note: "Otherwise we'll drive."),
                            TargetExpression(text: "might / can + verb", meaning: "Softer results.", note: "If it's cheap, we might buy it."),
                            TargetExpression(text: "What will happen if …?", meaning: "Ask about consequences.", note: "…if the flight is cancelled?"),
                            TargetExpression(text: "as long as / unless", meaning: "Condition cousins.", note: "unless = if not.")],
                situation: "You plan an outdoor birthday with a friend: set conditions for every possible problem (rain, no bus, cold) and what you'll do in each case.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "It may rain. Say what you will do. (stay in)", expected: ["If it rains, we'll stay in.", "If it rains, I'll stay in."], focus: "if + present, will", watch: "“If it will rain” — never will in the if-clause."),
                                PracticeQuestion(prompt: "The bus may not come. Predict lateness.", expected: ["If the bus doesn't come, we'll be late.", "We'll be late if the bus doesn't come."], focus: "negative condition", watch: "“If the bus won't come” — present simple after if."),
                                PracticeQuestion(prompt: "Offer an exchange of help.", expected: ["If you help me, I'll help you."], focus: "exchange", watch: "Both halves stay simple: present + will."),
                                PracticeQuestion(prompt: "Ask about a cancelled flight. (what / you / do)", expected: ["What will you do if the flight is cancelled?"], focus: "the conditional question", watch: "will goes in the result question, not after if."),
                                PracticeQuestion(prompt: "Soften the result: if it's cheap, maybe buy it.", expected: ["If it's cheap, I might buy it.", "If it's cheap, we might buy it."], focus: "might", watch: "might + base verb: “might to buy” is wrong."),
                                PracticeQuestion(prompt: "Say the alternative: no picnic → restaurant.", expected: ["If we can't have a picnic, we'll go to a restaurant.", "Otherwise, we'll go to a restaurant."], focus: "otherwise", watch: "Otherwise connects to the previous sentence's failure.")]),
                exercises: [
                            Exercise(id: "en-foundations-connections-first-conditional-e1", kind: "choice", prompt: "If it ___ tomorrow, we'll cancel the trip.", options: ["rains", "will rain", "rained", "is going to rain"], answers: ["rains"], explain: "The if-clause takes present simple."),
                            Exercise(id: "en-foundations-connections-first-conditional-e2", kind: "gap", prompt: "I'll call you if I ___ late. (be)", options: [], answers: ["am", "'m"], explain: "Present simple after if: if I am late."),
                            Exercise(id: "en-foundations-connections-first-conditional-e3", kind: "order", prompt: "Ask about a snow plan.", options: [], answers: ["What will you do if it snows"], explain: "Question word + will + you + do + if + present."),
                            Exercise(id: "en-foundations-connections-first-conditional-e4", kind: "written", prompt: "Fix: “If it will rain, we stay in.”", options: [], answers: ["if it rains we'll stay in", "if it rains we will stay in"], explain: "Present after if, will in the result.")], skills: ["grammar:first-conditional", "grammar:future-forms", "function:make-future-plans", "function:solve-problems"], canDo: ["make-future-plans"], prerequisites: ["grammar:present-simple", "grammar:going-to"]),
            Lesson(id: "en-foundations-connections-relative-clauses", title: "Relative clauses", goal: "Join ideas with who, which, that and where.",
                intro: LessonIntro(explanation: [
                            "who joins people, which joins things, that joins both (informal): “The woman who lives upstairs is a doctor.” “The book which won the prize…”",
                            "where joins places: “That's the café where we met.”",
                            "Shortened clauses: “The man standing there” (= who is standing). No double subject: “the book which won” not “the book which it won”."], examples: [
                            ExampleLine(text: "The woman who lives upstairs is a doctor.", meaning: "who + person."),
                            ExampleLine(text: "It's a film which changed cinema.", meaning: "which + thing."),
                            ExampleLine(text: "The song that she wrote became famous.", meaning: "that for people too (informal)."),
                            ExampleLine(text: "That's the café where we first met.", meaning: "where + place."),
                            ExampleLine(text: "The train (that) we caught was late.", meaning: "that can disappear as object."),
                            ExampleLine(text: "The guy standing by the door is my cousin.", meaning: "Shortened: who is standing.")]),
                expressions: [
                            TargetExpression(text: "the person who …", meaning: "Identify people.", note: "The person who called left a message."),
                            TargetExpression(text: "the thing which/that …", meaning: "Identify things.", note: "The app which tracks habits."),
                            TargetExpression(text: "the place where …", meaning: "Identify places.", note: "the street where I grew up."),
                            TargetExpression(text: "(that) … as object", meaning: "The joining word can vanish.", note: "the film (that) we saw."),
                            TargetExpression(text: "…, which …", meaning: "Comment on the whole sentence.", note: "He was late, which annoyed everyone."),
                            TargetExpression(text: "all / something + that", meaning: "Fixed pairs.", note: "All that matters is…")],
                situation: "You describe your neighbourhood to a visitor: the people who live there, the shops which are worth it and the corner where everything happens.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Describe your best friend. (person who…)", expected: ["My best friend is the person who knows me best.", "She's someone who always listens."], focus: "who", watch: "People take who (or that), never which."),
                                PracticeQuestion(prompt: "Describe an app you like. (app which…)", expected: ["It's an app which helps me study.", "It's an app that tracks my habits."], focus: "which/that", watch: "Things take which or that — both are fine here."),
                                PracticeQuestion(prompt: "Talk about the place you grew up. (where)", expected: ["The town where I grew up is small.", "I grew up in a village where everyone knew everyone."], focus: "where", watch: "where replaces “in which”: “the town where I grew up”."),
                                PracticeQuestion(prompt: "Join: “The train was late. We caught it.”", expected: ["The train (that) we caught was late."], focus: "dropping that", watch: "When the joiner is the object, that can disappear."),
                                PracticeQuestion(prompt: "Comment on a whole fact: “He resigned, … surprised everyone.”", expected: ["He resigned, which surprised everyone."], focus: ", which", watch: "Comma + which comments on the whole idea — never “, what surprised”."),
                                PracticeQuestion(prompt: "Fix: “The book which it won the prize is long.”", expected: ["the book which won the prize is long"], focus: "no double subject", watch: "which replaces it — never both.")]),
                exercises: [
                            Exercise(id: "en-foundations-connections-relative-clauses-e1", kind: "choice", prompt: "The woman ___ lives upstairs is a doctor.", options: ["who", "which", "where", "what"], answers: ["who"], explain: "People take who."),
                            Exercise(id: "en-foundations-connections-relative-clauses-e2", kind: "gap", prompt: "That's the café ___ we first met.", options: [], answers: ["where"], explain: "Places take where."),
                            Exercise(id: "en-foundations-connections-relative-clauses-e3", kind: "order", prompt: "Identify the film.", options: [], answers: ["It's a film which changed cinema"], explain: "which/that + verb."),
                            Exercise(id: "en-foundations-connections-relative-clauses-e4", kind: "written", prompt: "Join: “He resigned. It annoyed everyone.” (use which)", options: [], answers: ["he resigned which annoyed everyone"], explain: "He resigned, which annoyed everyone.")], skills: ["grammar:relative-clauses", "grammar:object-pronouns", "function:describe-people", "vocab:town"], canDo: ["express-opinion"], prerequisites: ["grammar:object-pronouns"]),
            Lesson(id: "en-foundations-connections-connectors", title: "Connectors: although, however, so", goal: "Link ideas with contrast (although, however) and result (so, because).",
                intro: LessonIntro(explanation: [
                            "Contrast: although + clause (“Although it was late, we went out”) and however + comma (“It was late. However, we went out.”).",
                            "Result: so joins cause → effect (“It was late, so we took a taxi”). Reason: because joins effect → cause (“We took a taxi because it was late”).",
                            "Punctuation: however needs a full stop or semicolon before it; although and because live inside the clause."], examples: [
                            ExampleLine(text: "Although it was expensive, we bought it.", meaning: "Contrast first."),
                            ExampleLine(text: "We bought it. However, we regret it now.", meaning: "However starts a new sentence."),
                            ExampleLine(text: "It was raining, so we stayed in.", meaning: "Cause → result."),
                            ExampleLine(text: "We stayed in because it was raining.", meaning: "Result → reason."),
                            ExampleLine(text: "The film was long; nevertheless, we enjoyed it.", meaning: "A formal contrast."),
                            ExampleLine(text: "Therefore, the plan changed.", meaning: "Formal result.")]),
                expressions: [
                            TargetExpression(text: "Although + clause, …", meaning: "Contrast inside one sentence.", note: "Although he's young, he leads the team."),
                            TargetExpression(text: "… . However, …", meaning: "Contrast between sentences.", note: "It works. However, it's slow."),
                            TargetExpression(text: "… , so + result", meaning: "Cause then result.", note: "It was full, so we left."),
                            TargetExpression(text: "… because + reason", meaning: "Result then reason.", note: "I left because it was full."),
                            TargetExpression(text: "Even though", meaning: "Stronger although.", note: "Even though I knew, I forgot."),
                            TargetExpression(text: "despite + noun/-ing", meaning: "Contrast without a clause.", note: "Despite the rain, we walked.")],
                situation: "You and a colleague review a project: what worked, what failed, and why — connecting every point with so, because, although and however.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Contrast in one sentence: it was expensive / we bought it. (although)", expected: ["Although it was expensive, we bought it."], focus: "although", watch: "although + full clause with a verb, not a noun."),
                                PracticeQuestion(prompt: "Contrast across two sentences: the plan works / it's slow. (however)", expected: ["The plan works. However, it's slow.", "The plan works; however, it's slow."], focus: "however", watch: "however needs a stop before it: full stop or semicolon."),
                                PracticeQuestion(prompt: "Cause and result: the shop was full / we left. (so)", expected: ["The shop was full, so we left."], focus: "so", watch: "so joins cause → result with just a comma."),
                                PracticeQuestion(prompt: "Same idea with because.", expected: ["We left because the shop was full."], focus: "because", watch: "because introduces the reason: result + because + reason."),
                                PracticeQuestion(prompt: "Stronger contrast: you knew / you forgot. (even though)", expected: ["Even though I knew, I forgot."], focus: "even though", watch: "Same grammar as although, stronger feeling."),
                                PracticeQuestion(prompt: "Contrast with a noun: the rain / we walked. (despite)", expected: ["Despite the rain, we walked.", "We walked despite the rain."], focus: "despite + noun", watch: "despite takes a noun or -ing, never a full clause.")]),
                exercises: [
                            Exercise(id: "en-foundations-connections-connectors-e1", kind: "choice", prompt: "___ it was late, we went out.", options: ["Although", "However", "So", "Because"], answers: ["Although"], explain: "although + clause expresses contrast."),
                            Exercise(id: "en-foundations-connections-connectors-e2", kind: "gap", prompt: "It was raining, ___ we stayed in. (result)", options: [], answers: ["so"], explain: "so introduces the result."),
                            Exercise(id: "en-foundations-connections-connectors-e3", kind: "order", prompt: "Give the reason for leaving.", options: [], answers: ["We left because it was full"], explain: "result + because + reason."),
                            Exercise(id: "en-foundations-connections-connectors-e4", kind: "written", prompt: "Fix: “The plan works, however it's slow.” (punctuation)", options: [], answers: ["the plan works however it's slow", "the plan works however it is slow"], explain: "However needs a stronger break: “The plan works. However, it's slow.”")], skills: ["grammar:connectors", "function:express-opinion", "speaking:justify-opinion", "writing:argument"], canDo: ["express-opinion"], prerequisites: ["grammar:present-simple"]),
            Lesson(id: "en-foundations-connections-suggestions", title: "Making suggestions", goal: "Propose plans with Why don't we, How about and Let's — and accept or decline kindly.",
                intro: LessonIntro(explanation: [
                            "Three openers, three grammars: Why don't we + verb (“Why don't we order pizza?”), How about + -ing (“How about watching a film?”), Let's + verb (“Let's stay in.”).",
                            "Accept: “Sounds good!” “Good idea!” Decline kindly with a reason and a counter-offer: “I'm beat, honestly. Rain check?”",
                            "Ask back with Shall we…? and What about…?: “Shall we meet at eight? What about the new place?”"], examples: [
                            ExampleLine(text: "Why don't we order pizza?", meaning: "why don't we + base verb."),
                            ExampleLine(text: "How about trying the new ramen place?", meaning: "how about + -ing."),
                            ExampleLine(text: "Let's stay in tonight.", meaning: "let's + base verb."),
                            ExampleLine(text: "Sounds good — I'm in!", meaning: "Accepting."),
                            ExampleLine(text: "I'm beat, honestly. Rain check?", meaning: "Declining kindly."),
                            ExampleLine(text: "Shall we say eight, then?", meaning: "Closing the plan.")]),
                expressions: [
                            TargetExpression(text: "Why don't we + verb", meaning: "Suggestion as a question.", note: "Never “Why we don't”."),
                            TargetExpression(text: "How about + -ing", meaning: "Suggestion with a gerund.", note: "How about going…?"),
                            TargetExpression(text: "Let's + verb", meaning: "Direct suggestion for both.", note: "Let's not argue."),
                            TargetExpression(text: "Sounds good / I'm in!", meaning: "Accept.", note: "sounds + adjective, no subject."),
                            TargetExpression(text: "Rain check?", meaning: "Not today, but soon.", note: "From ticket rain checks."),
                            TargetExpression(text: "Shall we say …?", meaning: "Fix the detail.", note: "Time or place closer.")],
                situation: "Friday night, no plan: trade suggestions, accept one, decline another kindly and settle on a time and place.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Suggest ordering food in. (why don't we)", expected: ["Why don't we order in?"], focus: "why don't we", watch: "“Why we don't order” — the inversion lives in don't we."),
                                PracticeQuestion(prompt: "Suggest watching a film. (how about)", expected: ["How about watching a film?"], focus: "how about + -ing", watch: "“How about to watch” — the gerund is obligatory."),
                                PracticeQuestion(prompt: "Suggest staying in, directly.", expected: ["Let's stay in tonight."], focus: "let's", watch: "let's + base verb: “let's to stay” is wrong."),
                                PracticeQuestion(prompt: "Accept a plan with enthusiasm.", expected: ["Sounds good — I'm in!", "Great idea, I'm in!"], focus: "accepting", watch: "“It sounds good” also works; “Sounds good” is the chatty form."),
                                PracticeQuestion(prompt: "Decline tonight, but keep the plan alive.", expected: ["I'm beat, honestly. Rain check?", "Can't tonight — rain check?"], focus: "declining", watch: "A decline without a counter-offer ends the friendship chat."),
                                PracticeQuestion(prompt: "Fix the time: eight.", expected: ["Shall we say eight, then?"], focus: "closing", watch: "shall we say + the detail.")]),
                exercises: [
                            Exercise(id: "en-foundations-connections-suggestions-e1", kind: "choice", prompt: "How about ___ the new exhibition?", options: ["visiting", "to visit", "visit", "we visit"], answers: ["visiting"], explain: "How about + -ing."),
                            Exercise(id: "en-foundations-connections-suggestions-e2", kind: "gap", prompt: "Why ___ we take a break? (suggestion)", options: [], answers: ["don't"], explain: "Why don't we + base verb."),
                            Exercise(id: "en-foundations-connections-suggestions-e3", kind: "order", prompt: "Suggest staying in.", options: [], answers: ["Let's stay in tonight"], explain: "Let's + base verb."),
                            Exercise(id: "en-foundations-connections-suggestions-e4", kind: "written", prompt: "Decline tonight kindly and keep it alive.", options: [], answers: ["i'm beat rain check", "cant tonight rain check", "i can't tonight rain check"], explain: "Reason + rain check.")], skills: ["function:make-suggestions", "grammar:gerunds-infinitives", "grammar:connectors", "speaking:sustained-conversation"], canDo: ["make-future-plans"], prerequisites: ["grammar:present-simple"])])
}

public enum EnFoundationsChange {
    public static let unit: CourseUnit = CourseUnit(id: "en-foundations-change", title: "Changes", subtitle: "Will, rumours, phrasal verbs", level: "B1", themes: [
                    ConversationTheme("weather-pool", "The office pool", "What will happen?", "cloud.sun", "Course", "You and your colleagues bet on next week: weather, results, deadlines. Make predictions and defend them.", 0),
                    ConversationTheme("rumour-mill", "The rumour mill", "Who said what?", "person.2.wave.2", "Course", "Office news travels fast: report what people said, and work out what is actually true.", 1)], lessons: [
            Lesson(id: "en-foundations-change-will", title: "Will: decisions & promises", goal: "Use will for spontaneous decisions, offers, promises and predictions without evidence.",
                intro: LessonIntro(explanation: [
                            "Will is for the moment of speaking: “The phone's ringing — I'll get it!” The decision happens as you talk.",
                            "It also covers promises and offers: “I'll always be there for you.” “I'll carry that for you.” And predictions without evidence: “You'll love this film.”",
                            "Contrast with going to: going to = already decided before speaking (“I'm going to study tonight”); will = decided now (“OK, I'll study with you”).",
                            "Negative: won't. Question: “Will you help me?” Never “will to help”."], examples: [
                            ExampleLine(text: "The phone's ringing — I'll get it!", meaning: "Decision at the moment of speaking."),
                            ExampleLine(text: "I'll carry that for you.", meaning: "An offer."),
                            ExampleLine(text: "I won't tell anyone, promise.", meaning: "A promise."),
                            ExampleLine(text: "Don't worry, you'll pass.", meaning: "A prediction, no evidence given."),
                            ExampleLine(text: "Shall I open the window? — Good idea, I'll close the door.", meaning: "Offers and instant decisions."),
                            ExampleLine(text: "I'm going to study tonight. — Great, I'll join you.", meaning: "Plan vs decision now.")]),
                expressions: [
                            TargetExpression(text: "I'll + verb", meaning: "Decision now, offer.", note: "I'll get the door."),
                            TargetExpression(text: "I won't + verb", meaning: "Promise not to.", note: "I won't be late."),
                            TargetExpression(text: "You'll love / it'll work", meaning: "Prediction without evidence.", note: "Contrast: it's going to rain (clouds!)."),
                            TargetExpression(text: "Will you …?", meaning: "Request or prediction question.", note: "Will you help me?"),
                            TargetExpression(text: "I think / probably + will", meaning: "Soften predictions.", note: "It'll probably rain."),
                            TargetExpression(text: "vs going to", meaning: "Decided now vs decided before.", note: "Both futures, different moments.")],
                situation: "A friend's flat has a small crisis (broken lamp, hungry cat, empty fridge): make instant offers, promises and confident predictions as events unfold.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "The doorbell rings while you're both cooking. Offer to answer.", expected: ["I'll get it!", "I'll answer it!"], focus: "decision now", watch: "“I'm going to get it” sounds pre-planned — the ring is news."),
                                PracticeQuestion(prompt: "Promise your friend you won't be late tomorrow.", expected: ["I won't be late.", "I promise I won't be late."], focus: "promise", watch: "“I won't to be” — won't + base verb."),
                                PracticeQuestion(prompt: "No evidence yet: predict your friend will love the film.", expected: ["You'll love the film.", "You're going to love it? no — use will: You'll love it."], focus: "bare prediction", watch: "Without evidence, will is the natural choice."),
                                PracticeQuestion(prompt: "Offer to carry the heavy boxes.", expected: ["I'll carry the boxes.", "I'll carry them for you."], focus: "offers", watch: "“I carry them” — English needs will for the offer."),
                                PracticeQuestion(prompt: "Soften your prediction about tonight's traffic. (probably)", expected: ["It'll probably be terrible.", "Traffic will probably be bad."], focus: "probably + will", watch: "probably goes before will: “will probably be”."),
                                PracticeQuestion(prompt: "Your friend says “I'm going to clean the kitchen”. Join in spontaneously.", expected: ["OK, I'll clean the bathroom!", "I'll help you then."], focus: "plan vs decision", watch: "Their plan = going to; your reaction = will.")]),
                exercises: [
                            Exercise(id: "en-foundations-change-will-e1", kind: "choice", prompt: "The phone's ringing — I ___ answer it.", options: ["'ll", "going to", "am", "do"], answers: ["'ll"], explain: "A decision at the moment of speaking takes will."),
                            Exercise(id: "en-foundations-change-will-e2", kind: "gap", prompt: "Don't worry, you ___ ___ fail. (negative promise)", options: [], answers: ["will not", "won't"], explain: "won't + base verb."),
                            Exercise(id: "en-foundations-change-will-e3", kind: "order", prompt: "Make a confident prediction.", options: [], answers: ["You will love this film"], explain: "will + base verb, no evidence needed."),
                            Exercise(id: "en-foundations-change-will-e4", kind: "written", prompt: "Your hands are full. Offer to be helped… no: offer help with the door.", options: [], answers: ["i'll open the door", "i will open the door", "i'll get the door"], explain: "I'll + verb for instant offers.")], skills: ["grammar:future-forms", "function:make-future-plans", "function:describe-goals", "speaking:short-answer"], canDo: ["make-future-plans"], prerequisites: ["grammar:verb-be", "grammar:going-to"]),
            Lesson(id: "en-foundations-change-reported", title: "He said he was busy", goal: "Report what people said with said/thought + a tense shift back.",
                intro: LessonIntro(explanation: [
                            "Direct: “I'm busy.” Reported: “He said he was busy.” The present shifts one step into the past.",
                            "Common shifts: am/is → was, are → were, will → would, can → could, have → had. Past simple usually stays past simple.",
                            "Questions drop their question form: “Where do you live?” → “She asked where I lived.” No do/did, no inversion."], examples: [
                            ExampleLine(text: "She said she was tired.", meaning: "“I am tired” → was."),
                            ExampleLine(text: "They said they would call.", meaning: "“We will call” → would."),
                            ExampleLine(text: "He told me he couldn't come.", meaning: "tell + person; say + (that)."),
                            ExampleLine(text: "You said you liked my cooking!", meaning: "“I like” → liked."),
                            ExampleLine(text: "She asked where I lived.", meaning: "Reported question, no did."),
                            ExampleLine(text: "I thought you were leaving today.", meaning: "thought + shift.")]),
                expressions: [
                            TargetExpression(text: "said (that) + shifted tense", meaning: "Report statements.", note: "He said (that) he was busy."),
                            TargetExpression(text: "told me + shifted tense", meaning: "Report to a person.", note: "tell SOMEONE; never “said me”."),
                            TargetExpression(text: "am/is → was", meaning: "The basic shift.", note: "“I'm here” → she said she was there."),
                            TargetExpression(text: "will → would / can → could", meaning: "Modals step back too.", note: "“I'll help” → he'd help."),
                            TargetExpression(text: "asked where/when/why + past", meaning: "Reported questions.", note: "No inversion, no do."),
                            TargetExpression(text: "Rumour mode: People are saying…", meaning: "Report gossip loosely.", note: "…the office is closing. Really?")],
                situation: "You come back from a day off to a wall of office rumours: report who said what, and separate reliable reports from gossip.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Report: “I'm leaving the company.” (Tom, to you)", expected: ["Tom said he was leaving the company.", "Tom told me he was leaving the company."], focus: "is → was", watch: "“Tom said he is leaving” is possible in casual speech — the exam-safe form shifts to was."),
                                PracticeQuestion(prompt: "Report: “We will announce it on Friday.” (the manager)", expected: ["The manager said they would announce it on Friday."], focus: "will → would", watch: "“said they will” — shift the modal too: would."),
                                PracticeQuestion(prompt: "Report: “I can't find the file.” (Ana)", expected: ["Ana said she couldn't find the file.", "Ana told me she couldn't find the file."], focus: "can → could", watch: "Never “said me” — say (that) or told me."),
                                PracticeQuestion(prompt: "Report the question: “Where do you work?”", expected: ["She asked where I worked."], focus: "reported question", watch: "No did, no inversion: “asked where did I work” is wrong."),
                                PracticeQuestion(prompt: "Pass on gossip about the merger. (People are saying…)", expected: ["People are saying the merger is off.", "People are saying there's going to be a merger."], focus: "rumour mode", watch: "are saying keeps it vague and deniable."),
                                PracticeQuestion(prompt: "Correct a rumour: “I thought you were leaving, but you're not.”", expected: ["I thought you were leaving, but you're still here.", "I thought you were leaving — obviously not!"], focus: "thought + shift", watch: "thought + was for the belief you had.")]),
                exercises: [
                            Exercise(id: "en-foundations-change-reported-e1", kind: "choice", prompt: "She ___ she was tired.", options: ["said", "told", "says to", "spoke"], answers: ["said"], explain: "say (that) + clause; tell needs a person: told ME."),
                            Exercise(id: "en-foundations-change-reported-e2", kind: "gap", prompt: "They said they ___ call later. (will → shift)", options: [], answers: ["would", "'d"], explain: "will steps back to would."),
                            Exercise(id: "en-foundations-change-reported-e3", kind: "order", prompt: "Report this question. (asked / I / where / she / lived)", options: [], answers: ["She asked where I lived"], explain: "asked + question word + subject + past."),
                            Exercise(id: "en-foundations-change-reported-e4", kind: "written", prompt: "Fix: “He said me he is busy.”", options: [], answers: ["he told me he was busy", "he said he was busy"], explain: "said me doesn't exist; and is shifts to was.")], skills: ["grammar:reported-speech-basic", "grammar:past-simple-irregular", "function:tell-a-story", "vocab:work"], canDo: ["tell-a-story"], prerequisites: ["grammar:past-simple-irregular"]),
            Lesson(id: "en-foundations-change-phrasals", title: "Phrasal verbs you already use", goal: "Master the ten everyday phrasal verbs that replace formal verbs in speech.",
                intro: LessonIntro(explanation: [
                            "A phrasal verb = verb + particle with its own meaning: get up (leave the bed), give up (stop trying), look for (search). The particle changes everything.",
                            "Separable or not: “turn it off” (separable — the pronoun goes in the middle, never at the end). “Look after the cat” (inseparable). Learn each verb's habit.",
                            "Formal English often has a single-verb twin: find out = discover, put off = postpone. Speech prefers the phrasal; writing accepts both."], examples: [
                            ExampleLine(text: "I get up at six even on Sundays.", meaning: "leave the bed."),
                            ExampleLine(text: "Don't give up now!", meaning: "stop trying."),
                            ExampleLine(text: "I'm looking for my keys.", meaning: "searching."),
                            ExampleLine(text: "Turn it off and back on again.", meaning: "Separable: turn the computer off."),
                            ExampleLine(text: "Can you look after the cat this weekend?", meaning: "Inseparable: take care of."),
                            ExampleLine(text: "I found out the truth yesterday.", meaning: "= discovered.")]),
                expressions: [
                            TargetExpression(text: "get up", meaning: "Leave the bed.", note: "I got up late."),
                            TargetExpression(text: "give up", meaning: "Stop trying.", note: "give up + -ing: give up smoking."),
                            TargetExpression(text: "look for / look after", meaning: "Search / take care of.", note: "Different meanings, same verb."),
                            TargetExpression(text: "turn on/off (separable)", meaning: "Pronoun in the middle.", note: "turn it on, never turn on it."),
                            TargetExpression(text: "find out", meaning: "= discover.", note: "I'll find out and tell you."),
                            TargetExpression(text: "put off = postpone", meaning: "Formal twin exists.", note: "They put off the meeting.")],
                situation: "A friend is moving house: phrasal verbs everywhere — get up early, pick up boxes, look after the dog, give up the sofa, turn off the lights.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Say what time you leave the bed on Mondays.", expected: ["I get up at <time> on Mondays."], focus: "get up", watch: "“I get me up” — no pronoun: I get up."),
                                PracticeQuestion(prompt: "Encourage a friend who wants to quit the gym to continue.", expected: ["Don't give up!"], focus: "give up", watch: "give up alone works: no object needed."),
                                PracticeQuestion(prompt: "Ask someone to take care of your dog this weekend.", expected: ["Can you look after my dog this weekend?"], focus: "look after", watch: "look after ≠ look for (search)."),
                                PracticeQuestion(prompt: "The pronoun goes in the middle: the lights / turn off / them.", expected: ["Turn them off.", "Turn off the lights.", "Turn the lights off."], focus: "separable", watch: "“Turn off them” is wrong — pronouns sit inside."),
                                PracticeQuestion(prompt: "Say you discovered the truth yesterday. (phrasal)", expected: ["I found out the truth yesterday."], focus: "find out", watch: "found out, not “found up” or “discovered out”."),
                                PracticeQuestion(prompt: "Say the meeting was postponed. (phrasal)", expected: ["They put off the meeting.", "The meeting was put off."], focus: "put off", watch: "put off + thing; put the meeting off also works.")]),
                exercises: [
                            Exercise(id: "en-foundations-change-phrasals-e1", kind: "choice", prompt: "Can you ___ ___ my plants while I'm away?", options: ["look after", "look for", "look up", "look at"], answers: ["look after"], explain: "look after = take care of; look for = search."),
                            Exercise(id: "en-foundations-change-phrasals-e2", kind: "gap", prompt: "Turn ___ ___ before you leave. (the lights, pronoun)", options: [], answers: ["them off", "it off"], explain: "Separable: the pronoun goes inside."),
                            Exercise(id: "en-foundations-change-phrasals-e3", kind: "order", prompt: "Encourage your friend.", options: [], answers: ["Don't give up now"], explain: "don't give up = keep trying."),
                            Exercise(id: "en-foundations-change-phrasals-e4", kind: "written", prompt: "Phrasal twin: “They postponed the meeting.”", options: [], answers: ["they put off the meeting", "they put the meeting off"], explain: "put off = postpone.")], skills: ["grammar:phrasal-verbs", "vocab:daily-routine", "function:talk-about-routines"], canDo: ["talk-about-routines"], prerequisites: ["grammar:present-simple"])])
}

public enum EnFoundationsTelling {
    public static let unit: CourseUnit = CourseUnit(id: "en-foundations-telling", title: "Telling it well", subtitle: "Collocations, reactions, problems", level: "B1", themes: [
                    ConversationTheme("good-news-bad-news", "Good news, bad news", "React naturally", "arrow.up.arrow.down", "Course", "You swap news with a friend: some wonderful, some terrible — your reactions carry the conversation.", 0),
                    ConversationTheme("the-broken-thing", "The broken thing", "Explain and fix", "wrench.and.screwdriver", "Course", "Something you rented is broken. Explain the problem clearly and agree on a solution.", 1)], lessons: [
            Lesson(id: "en-foundations-telling-collocations", title: "Collocations that carry you", goal: "Use the word pairs natives reach for: make a decision, have a break, pay attention.",
                intro: LessonIntro(explanation: [
                            "Collocations are fixed friendships between words: make a decision (never do a decision), pay attention, take responsibility.",
                            "Learn them as whole chunks: word-by-word assembly is how “do a mistake” happens — mistakes are made.",
                            "When unsure, ask a native: “What's the usual verb here?” They hear the pair, not the rule."], examples: [
                            ExampleLine(text: "We need to make a decision today.", meaning: "make + decision."),
                            ExampleLine(text: "Let's have a break.", meaning: "have + break/rest."),
                            ExampleLine(text: "Pay attention to the deadline.", meaning: "pay + attention."),
                            ExampleLine(text: "I made a mistake in the report.", meaning: "make + mistake."),
                            ExampleLine(text: "She takes responsibility for the project.", meaning: "take + responsibility.")]),
                expressions: [
                            TargetExpression(text: "make a decision / mistake", meaning: "The two makes.", note: "Never do a decision."),
                            TargetExpression(text: "have a break / rest", meaning: "have + rest words.", note: "Let's have a break."),
                            TargetExpression(text: "pay attention (to)", meaning: "Focus.", note: "…to the details."),
                            TargetExpression(text: "take responsibility / a seat", meaning: "take pairs.", note: "take your time."),
                            TargetExpression(text: "do someone a favour", meaning: "do + favour.", note: "Can you do me a favour?"),
                            TargetExpression(text: "heavy traffic / light rain", meaning: "Adjective pairs.", note: "The traffic is heavy.")],
                situation: "You and a colleague polish an email together: swap the literal phrases for natural collocations — decision, break, mistake, favour — and feel it sound native.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Say it with the right verb: decide today. (make a decision)", expected: ["We need to make a decision today."], focus: "make a decision", watch: "Never “do a decision” — decision pairs with make."),
                                PracticeQuestion(prompt: "Correct the classic error: “I did a mistake”.", expected: ["I made a mistake."], focus: "make a mistake", watch: "do → made: mistakes are made."),
                                PracticeQuestion(prompt: "Ask a colleague for a favour.", expected: ["Can you do me a favour?"], focus: "do a favour", watch: "favours are done, mistakes are made."),
                                PracticeQuestion(prompt: "Tell a restless team to pause.", expected: ["Let's have a break."], focus: "have a break", watch: "have a break / have a rest — both natural."),
                                PracticeQuestion(prompt: "Describe the traffic at five o'clock.", expected: ["The traffic is really heavy."], focus: "heavy traffic", watch: "traffic is heavy or light — never “big traffic”.")]),
                exercises: [
                            Exercise(id: "en-foundations-telling-collocations-e1", kind: "choice", prompt: "We need to ___ a decision before Friday.", options: ["make", "do", "have", "take"], answers: ["make"], explain: "make a decision — the fixed pair."),
                            Exercise(id: "en-foundations-telling-collocations-e2", kind: "gap", prompt: "I ___ a mistake in the report. Sorry.", options: [], answers: ["made"], explain: "make → made a mistake."),
                            Exercise(id: "en-foundations-telling-collocations-e3", kind: "order", prompt: "Ask for a favour.", options: [], answers: ["Can you do me a favour"], explain: "do someone a favour."),
                            Exercise(id: "en-foundations-telling-collocations-e4", kind: "written", prompt: "Describe the traffic at rush hour.", options: [], answers: ["the traffic is heavy", "traffic is really heavy"], explain: "heavy traffic.")], skills: ["vocab:collocations", "vocab:social-expressions", "grammar:present-simple", "function:express-opinion"], canDo: ["express-opinion"], prerequisites: ["grammar:present-simple"]),
            Lesson(id: "en-foundations-telling-reacting", title: "Reacting to news", goal: "Respond to good and bad news naturally — the reactions carry the conversation.",
                intro: LessonIntro(explanation: [
                            "Good news reactions, in rising order: “Nice!” “That's great news!” “No way! That's amazing!”",
                            "Bad news: “Oh no.” “I'm sorry to hear that.” “That's awful.” Then the follow-up question — reactions without questions are walls.",
                            "The secret: react, then ask. “No way! When did that happen?” — the question proves you care."], examples: [
                            ExampleLine(text: "No way! That's amazing!", meaning: "Big good news."),
                            ExampleLine(text: "That's great news, congratulations!", meaning: "Good news + congratulation."),
                            ExampleLine(text: "Oh no, I'm sorry to hear that.", meaning: "Bad news."),
                            ExampleLine(text: "That's awful — are you OK?", meaning: "Bad news + care."),
                            ExampleLine(text: "Really? When did that happen?", meaning: "React + follow-up.")]),
                expressions: [
                            TargetExpression(text: "No way!", meaning: "Surprise, good or bad.", note: "Strong but friendly."),
                            TargetExpression(text: "That's great news!", meaning: "Good news reaction.", note: "news is singular!"),
                            TargetExpression(text: "I'm sorry to hear that.", meaning: "Bad news reaction.", note: "Fixed phrase."),
                            TargetExpression(text: "Congratulations!", meaning: "Achievements.", note: "congratulations on + thing."),
                            TargetExpression(text: "React + question", meaning: "Keep it flowing.", note: "No way! When?")],
                situation: "A friend calls with a promotion; another cancels with a family emergency; a third has bought a boat. React to each — differently, and always with a question.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "React to big good news: your friend got promoted.", expected: ["No way! Congratulations!", "That's amazing — congratulations!"], focus: "big good news", watch: "congratulations on the promotion."),
                                PracticeQuestion(prompt: "React to very bad news: your friend's dog died.", expected: ["Oh no, I'm so sorry.", "I'm so sorry to hear that."], focus: "bad news", watch: "Match the weight: “Nice!” would be terrible."),
                                PracticeQuestion(prompt: "React and ask for details about a new job.", expected: ["That's great! When do you start?"], focus: "react + question", watch: "The follow-up keeps the conversation alive."),
                                PracticeQuestion(prompt: "React to a surprise: your friend bought a boat.", expected: ["No way! You bought a boat?", "You're kidding!"], focus: "surprise", watch: "You're kidding! = no me lo creo."),
                                PracticeQuestion(prompt: "Move from bad news to care.", expected: ["That's awful — are you OK?"], focus: "care question", watch: "Awful news gets a care question, not curiosity.")]),
                exercises: [
                            Exercise(id: "en-foundations-telling-reacting-e1", kind: "choice", prompt: "That's wonderful ___!", options: ["news", "new", "a news", "newses"], answers: ["news"], explain: "news is uncountable: news is, never newses."),
                            Exercise(id: "en-foundations-telling-reacting-e2", kind: "gap", prompt: "Congratulations ___ your promotion!", options: [], answers: ["on"], explain: "congratulations on + thing."),
                            Exercise(id: "en-foundations-telling-reacting-e3", kind: "order", prompt: "React to bad news.", options: [], answers: ["Im sorry to hear that"], explain: "I'm sorry to hear that."),
                            Exercise(id: "en-foundations-telling-reacting-e4", kind: "written", prompt: "React with surprise to a boat purchase.", options: [], answers: ["no way", "youre kidding", "no way you bought a boat"], explain: "Any natural surprise.")], skills: ["vocab:social-expressions", "function:express-opinion", "speaking:sustained-conversation", "grammar:present-simple"], canDo: ["express-opinion"], prerequisites: ["grammar:present-simple"]),
            Lesson(id: "en-foundations-telling-problems", title: "Explaining a problem", goal: "Structure a problem clearly: context, what happened, what you want.",
                intro: LessonIntro(explanation: [
                            "The three-step structure: context (“I rented a car on Friday”), problem (“it broke down on the motorway”), request (“I'd like a refund or a replacement”).",
                            "Stay factual, not emotional: “The engine stopped three times” beats “your car is terrible!”",
                            "Signal the request: “So what I'd like is…” — the listener knows the explanation has landed somewhere."], examples: [
                            ExampleLine(text: "I rented a car from your airport office.", meaning: "Context first."),
                            ExampleLine(text: "It broke down twice on Saturday.", meaning: "The problem, factually."),
                            ExampleLine(text: "I'd like a replacement or a refund.", meaning: "The request."),
                            ExampleLine(text: "This is the second time it's happened.", meaning: "History strengthens the case."),
                            ExampleLine(text: "What can you do about it?", meaning: "Hand the problem over.")]),
                expressions: [
                            TargetExpression(text: "Context first: …", meaning: "Set the scene.", note: "I bought it last week."),
                            TargetExpression(text: "The problem is …", meaning: "Say it plainly.", note: "…it doesn't charge."),
                            TargetExpression(text: "I'd like …", meaning: "State the request.", note: "I'd like a replacement."),
                            TargetExpression(text: "This is the second time …", meaning: "Show the pattern.", note: "…it's happened."),
                            TargetExpression(text: "What can you do about it?", meaning: "Pass the ball.", note: "Polite but firm.")],
                situation: "You call about a faulty rental: give context, describe the two failures factually, and ask for one of two clear solutions.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Give the context of your complaint. (rented Friday)", expected: ["I rented a car from your office on Friday."], focus: "context", watch: "Dates and places first — emotions later (or never)."),
                                PracticeQuestion(prompt: "Describe the failure factually. (broke down twice)", expected: ["It broke down twice on Saturday."], focus: "factual", watch: "Twice is a fact; “terrible” is an opinion."),
                                PracticeQuestion(prompt: "State your request clearly.", expected: ["I'd like a replacement or a refund."], focus: "the request", watch: "Two options make agreement easier."),
                                PracticeQuestion(prompt: "Show it's a pattern. (second time)", expected: ["This is the second time it's happened."], focus: "the pattern", watch: "Second time strengthens the case."),
                                PracticeQuestion(prompt: "Hand the problem to them.", expected: ["What can you do about it?"], focus: "pass the ball", watch: "The question puts them on the hook, politely.")]),
                exercises: [
                            Exercise(id: "en-foundations-telling-problems-e1", kind: "choice", prompt: "I'd like ___ refund, please.", options: ["a", "an", "some", "the my"], answers: ["a"], explain: "a refund — consonant sound."),
                            Exercise(id: "en-foundations-telling-problems-e2", kind: "gap", prompt: "The engine ___ ___ three times. (stop, past)", options: [], answers: ["stopped"], explain: "stop → stopped."),
                            Exercise(id: "en-foundations-telling-problems-e3", kind: "order", prompt: "State your request.", options: [], answers: ["Id like a replacement or a refund"], explain: "I'd like + option or option."),
                            Exercise(id: "en-foundations-telling-problems-e4", kind: "written", prompt: "Open a complaint: you bought a phone last week.", options: [], answers: ["i bought a phone last week", "i bought this phone last week"], explain: "Context: what, when.")], skills: ["function:solve-problems", "grammar:past-simple-regular", "grammar:connectors", "vocab:social-expressions"], canDo: ["solve-everyday-problems"], prerequisites: ["grammar:past-simple-regular"])])
}

public enum EnFoundationsViewpoints {
    public static let unit: CourseUnit = CourseUnit(id: "en-foundations-viewpoints", title: "Viewpoints", subtitle: "Argue, report, imagine", level: "B2", themes: [
                    ConversationTheme("debate-club", "Debate night", "Take a side", "person.3", "Course", "You debate a topical question: state your position, imagine alternatives, report what the data says.", 0),
                    ConversationTheme("negotiation-table", "The negotiation", "Find the middle", "scale.3d", "Course", "You negotiate a work arrangement: conditions, consequences and a deal both sides can accept.", 1)], lessons: [
            Lesson(id: "en-foundations-viewpoints-second-conditional", title: "Second conditional", goal: "Imagine unreal presents and alternatives with if + past, would + verb.",
                intro: LessonIntro(explanation: [
                            "Unreal presents use if + past simple, would + verb: “If I had more time, I would learn the piano.” The time is now/forward — the past form only marks unreality.",
                            "Questions: “What would you do if you lost your job?” I'd = I would.",
                            "Softer advice uses would in the result: “If I were you, I'd negotiate.” Note the fixed phrase If I were you."], examples: [
                            ExampleLine(text: "If I won the lottery, I would travel for a year.", meaning: "An unreal present."),
                            ExampleLine(text: "If I were you, I'd ask for a raise.", meaning: "Advice with were."),
                            ExampleLine(text: "Would you move abroad if you got the chance?", meaning: "Question form."),
                            ExampleLine(text: "I wouldn't say that if I weren't sure.", meaning: "Negative on both sides."),
                            ExampleLine(text: "If we had a bigger budget, we could hire help.", meaning: "could = would be able to."),
                            ExampleLine(text: "Compare: “If it rains, we'll stay” (real) vs “If it rained, we'd stay” (unlikely).", meaning: "First vs second conditional.")]),
                expressions: [
                            TargetExpression(text: "If + past, would + verb", meaning: "Unreal present.", note: "If I had time, I would cook."),
                            TargetExpression(text: "If I were you, I'd …", meaning: "The advice formula.", note: "were, not was, in formal English."),
                            TargetExpression(text: "What would you do if …?", meaning: "The hypothetical question.", note: "Perfect for debates."),
                            TargetExpression(text: "I'd never …", meaning: "A firm unreal negative.", note: "I'd never lie to a client."),
                            TargetExpression(text: "could / might instead of would", meaning: "Ability or possibility in the result.", note: "If we left now, we could catch it."),
                            TargetExpression(text: "Compare with first conditional", meaning: "Real vs imaginary.", note: "If I win… (possible) vs If I won… (fantasy).")],
                situation: "A debate table: what would you do with a year off, a sudden fortune, a job abroad? Defend your hypotheticals and challenge theirs.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Imagine you had a year off. What would you do?", expected: ["If I had a year off, I would <activity>.", "I'd <activity>."], focus: "if + past, would", watch: "“If I would have a year” — never would in the if-clause."),
                                PracticeQuestion(prompt: "Give advice to a friend who earns too little. (If I were you…)", expected: ["If I were you, I'd ask for a raise.", "If I were you, I would look for another job."], focus: "If I were you", watch: "The fixed advice formula uses were."),
                                PracticeQuestion(prompt: "Ask about your friend's hypothetical move abroad.", expected: ["Would you move abroad if you got the chance?"], focus: "would question", watch: "would in the result question; past in the if-clause."),
                                PracticeQuestion(prompt: "Say what is possible, not certain: if we left now / catch the train.", expected: ["If we left now, we could catch the train."], focus: "could in the result", watch: "could replaces would for possibility."),
                                PracticeQuestion(prompt: "Contrast real vs imaginary: rain tomorrow / money for a trip.", expected: ["If it rains tomorrow, we'll cancel. If I had money for a trip, I'd go today."], focus: "first vs second", watch: "Real future takes present+will; fantasy takes past+would."),
                                PracticeQuestion(prompt: "Firm unreal negative: lie to a client.", expected: ["I'd never lie to a client.", "I would never lie to a client."], focus: "I'd never", watch: "would + never + base verb.")]),
                exercises: [
                            Exercise(id: "en-foundations-viewpoints-second-conditional-e1", kind: "choice", prompt: "If I ___ more time, I would learn the piano.", options: ["had", "have", "would have", "will have"], answers: ["had"], explain: "Unreal present: if + past simple."),
                            Exercise(id: "en-foundations-viewpoints-second-conditional-e2", kind: "gap", prompt: "If I were you, I ___ ask for a raise.", options: [], answers: ["would", "'d"], explain: "would in the result: I'd ask."),
                            Exercise(id: "en-foundations-viewpoints-second-conditional-e3", kind: "order", prompt: "Ask the hypothetical question. (move / would / if / you / abroad / the chance / you / got)", options: [], answers: ["Would you move abroad if you got the chance"], explain: "would question + if + past."),
                            Exercise(id: "en-foundations-viewpoints-second-conditional-e4", kind: "written", prompt: "Fix: “If I would have time, I would cook.”", options: [], answers: ["if i had time i would cook"], explain: "The if-clause takes had, never would have.")], skills: ["grammar:second-conditional", "grammar:first-conditional", "function:express-opinion", "speaking:justify-opinion"], canDo: ["express-opinion"], prerequisites: ["grammar:past-simple-irregular", "grammar:first-conditional"]),
            Lesson(id: "en-foundations-viewpoints-passive", title: "The passive: reporting", goal: "Report information with is/are/was/were + past participle when the doer is unknown or unimportant.",
                intro: LessonIntro(explanation: [
                            "Passive = be + past participle: “The bridge was built in 1900.” “These shoes are made in Portugal.” The doer disappears or moves to a by-phrase.",
                            "Use it when the doer is obvious, unknown or unimportant — the classic register of news, reports and instructions.",
                            "Questions and negatives behave like be: “Was it built recently?” “It isn't sold here.”"], examples: [
                            ExampleLine(text: "The results will be published tomorrow.", meaning: "Future passive."),
                            ExampleLine(text: "This bridge was built in 1900.", meaning: "Past passive."),
                            ExampleLine(text: "These shoes are made in Portugal.", meaning: "Present passive."),
                            ExampleLine(text: "The novel was written by a nurse.", meaning: "by + the important doer."),
                            ExampleLine(text: "Payment must be made in advance.", meaning: "Modal + passive."),
                            ExampleLine(text: "Was the email sent?", meaning: "Passive question.")]),
                expressions: [
                            TargetExpression(text: "is/are + participle", meaning: "Present facts.", note: "The office is cleaned daily."),
                            TargetExpression(text: "was/were + participle", meaning: "Past events.", note: "It was designed by Gaudí."),
                            TargetExpression(text: "will be + participle", meaning: "Future plans.", note: "The report will be shared on Monday."),
                            TargetExpression(text: "must be + participle", meaning: "Rules and instructions.", note: "Tickets must be validated."),
                            TargetExpression(text: "by + doer", meaning: "Only when the doer matters.", note: "Hamlet was written by Shakespeare."),
                            TargetExpression(text: "It is said that …", meaning: "Reporting without a source.", note: "It is said that the lake is bottomless.")],
                situation: "You present a short report about your town's history: what was built, what is produced there and what will be opened next year.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Report a past fact: they built the theatre in 1921. (passive)", expected: ["The theatre was built in 1921."], focus: "was + participle", watch: "“was build” — the participle is built."),
                                PracticeQuestion(prompt: "State a present fact: they make these shoes in Portugal. (passive)", expected: ["These shoes are made in Portugal."], focus: "are + participle", watch: "“are make” — participle, not base form."),
                                PracticeQuestion(prompt: "Announce a plan: they will publish the results tomorrow. (passive)", expected: ["The results will be published tomorrow."], focus: "will be + participle", watch: "“will published” — be comes first: will be published."),
                                PracticeQuestion(prompt: "State a rule: you must validate tickets. (passive)", expected: ["Tickets must be validated."], focus: "must be", watch: "Modal + be + participle."),
                                PracticeQuestion(prompt: "The doer matters here. Join: “Shakespeare wrote Hamlet.” Keep Shakespeare. (passive)", expected: ["Hamlet was written by Shakespeare."], focus: "by + doer", watch: "by appears only when the doer is important information."),
                                PracticeQuestion(prompt: "Ask about a past event in passive form. (the email / send)", expected: ["Was the email sent?"], focus: "passive question", watch: "be moves to the front: Was it sent?")]),
                exercises: [
                            Exercise(id: "en-foundations-viewpoints-passive-e1", kind: "choice", prompt: "These computers ___ in Taiwan.", options: ["are made", "are making", "made", "is made"], answers: ["are made"], explain: "Plural present passive: are made."),
                            Exercise(id: "en-foundations-viewpoints-passive-e2", kind: "gap", prompt: "The parcel ___ ___ delivered tomorrow. (will, passive)", options: [], answers: ["will be"], explain: "will be + participle."),
                            Exercise(id: "en-foundations-viewpoints-passive-e3", kind: "order", prompt: "Report the rule.", options: [], answers: ["Tickets must be validated before boarding"], explain: "modal + be + participle."),
                            Exercise(id: "en-foundations-viewpoints-passive-e4", kind: "written", prompt: "Fix: “The house was build in 1990.”", options: [], answers: ["the house was built in 1990"], explain: "build → built: the participle.")], skills: ["grammar:passive-intro", "grammar:past-simple-regular", "function:talk-about-work", "writing:email"], canDo: ["talk-about-work"], prerequisites: ["grammar:past-simple-regular", "grammar:verb-be"]),
            Lesson(id: "en-foundations-viewpoints-negotiation", title: "Negotiating", goal: "Negotiate politely: propose conditions, concede ground and close a deal.",
                intro: LessonIntro(explanation: [
                            "Proposals soften with could/would: “Could we possibly move the deadline?” “Would it help if I took the night shift?”",
                            "Concede with a condition: “That works if…”, “As long as…, I'm happy to…”. Push back without conflict: “I see your point, however…”",
                            "Close: “Shall we say…?”, “So we agree on…”, “I think we have a deal.”"], examples: [
                            ExampleLine(text: "Could we possibly start at ten?", meaning: "A softened proposal."),
                            ExampleLine(text: "That works if the report arrives on Thursday.", meaning: "A conditional yes."),
                            ExampleLine(text: "As long as I keep Fridays free, I'm happy to travel.", meaning: "As long as = condition."),
                            ExampleLine(text: "I see your point; however, the budget is fixed.", meaning: "Pushback without conflict."),
                            ExampleLine(text: "What if we split the difference?", meaning: "A middle-ground move."),
                            ExampleLine(text: "Shall we say thirty percent?", meaning: "The closing formula.")]),
                expressions: [
                            TargetExpression(text: "Could we possibly …?", meaning: "A polite proposal.", note: "possibly = extra soft."),
                            TargetExpression(text: "That works if …", meaning: "Yes, with a condition.", note: "Condition first, then agreement."),
                            TargetExpression(text: "as long as …", meaning: "Your red lines.", note: "As long as costs stay under X."),
                            TargetExpression(text: "I see your point; however …", meaning: "Respectful disagreement.", note: "Acknowledge, then contrast."),
                            TargetExpression(text: "What if we …?", meaning: "Offer a middle path.", note: "What if we split the costs?"),
                            TargetExpression(text: "Shall we say …?", meaning: "Close the deal.", note: "Numbers finish negotiations.")],
                situation: "You negotiate a remote-work arrangement with your manager: propose, concede, push back once and close with a concrete deal.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Politely propose a later start time.", expected: ["Could we possibly start at ten?", "Would it be possible to start later?"], focus: "softened proposal", watch: "Bare commands sound abrupt in negotiation; use could/would."),
                                PracticeQuestion(prompt: "Accept travelling, with one condition. (as long as)", expected: ["That works as long as I keep Fridays free.", "As long as costs are covered, I'm happy to travel."], focus: "as long as", watch: "as long as + present simple for your condition."),
                                PracticeQuestion(prompt: "Disagree respectfully with a tight deadline.", expected: ["I see your point; however, the deadline is too tight.", "I understand, however we need two more days."], focus: "acknowledge + however", watch: "Acknowledge first — however lands softer after agreement words."),
                                PracticeQuestion(prompt: "Offer a middle ground on price.", expected: ["What if we split the difference?", "What if we meet in the middle?"], focus: "what if", watch: "what if + present simple proposes the path."),
                                PracticeQuestion(prompt: "Close the deal on a number. (thirty percent)", expected: ["Shall we say thirty percent?"], focus: "closing", watch: "shall we say + the final number."),
                                PracticeQuestion(prompt: "State the deal you both reached.", expected: ["So we agree on: remote Mondays and a Thursday report.", "So we agree: I travel twice a month, you cover the costs."], focus: "summarising", watch: "Good negotiators summarise: “So we agree on…”.")]),
                exercises: [
                            Exercise(id: "en-foundations-viewpoints-negotiation-e1", kind: "choice", prompt: "___ we possibly move the meeting to Thursday?", options: ["Could", "Must", "Will", "Should"], answers: ["Could"], explain: "Could we possibly…? is the softest proposal."),
                            Exercise(id: "en-foundations-viewpoints-negotiation-e2", kind: "gap", prompt: "That works ___ ___ as the budget is approved. (2 words: condition)", options: [], answers: ["as long", "so long"], explain: "as long as / so long as = siempre que."),
                            Exercise(id: "en-foundations-viewpoints-negotiation-e3", kind: "order", prompt: "Respectfully disagree.", options: [], answers: ["I see your point however the budget is fixed"], explain: "Acknowledge, then contrast."),
                            Exercise(id: "en-foundations-viewpoints-negotiation-e4", kind: "written", prompt: "Close a deal at ten percent.", options: [], answers: ["shall we say ten percent", "shall we say 10 percent", "shall we say 10%"], explain: "Shall we say + number closes it.")], skills: ["function:negotiate", "grammar:second-conditional", "grammar:connectors", "speaking:negotiate", "vocab:work"], canDo: ["solve-everyday-problems"], prerequisites: ["grammar:connectors", "grammar:modal-should"])])
}

public enum EnFoundationsMedia {
    public static let unit: CourseUnit = CourseUnit(id: "en-foundations-media", title: "Media & argument", subtitle: "News, claims, debate", level: "B2", themes: [
                    ConversationTheme("editorial-meeting", "The editorial meeting", "What's the story?", "newspaper", "Course", "You pitch a story: what happened, why now, why anyone should care — in ninety seconds.", 0),
                    ConversationTheme("letters-page", "The letters page", "Claim and counter", "envelope", "Course", "You respond to an opinion piece: concede a point, then dismantle it politely.", 1)], lessons: [
            Lesson(id: "en-foundations-media-news-language", title: "The language of news", goal: "Read and report news: passive reporting, headline grammar and attribution.",
                intro: LessonIntro(explanation: [
                            "Headlines drop words: “Bridge reopened after repairs” = The bridge has been reopened. Learn to expand them.",
                            "Attribution protects reporters: “It is believed that…”, “according to sources”. Nobody said it; it is said.",
                            "The passive rules news because events matter more than doers: “Measures were announced” — by whom, later, maybe."], examples: [
                            ExampleLine(text: "Bridge reopened after repairs.", meaning: "A headline: expand to a full sentence."),
                            ExampleLine(text: "It is believed that costs will fall.", meaning: "Attribution without a source."),
                            ExampleLine(text: "Measures were announced on Tuesday.", meaning: "Event-focused passive."),
                            ExampleLine(text: "The minister is thought to favour delays.", meaning: "is thought to + verb."),
                            ExampleLine(text: "According to the report, numbers fell.", meaning: "according to = the source.")]),
                expressions: [
                            TargetExpression(text: "… was/were + participle", meaning: "The reporting backbone.", note: "The road was closed."),
                            TargetExpression(text: "It is said/believed that …", meaning: "Source-free attribution.", note: "It is believed that…"),
                            TargetExpression(text: "is thought to + verb", meaning: "Report others' claims.", note: "He is thought to have left."),
                            TargetExpression(text: "according to …", meaning: "Name the source.", note: "according to the report."),
                            TargetExpression(text: "are expected to + verb", meaning: "Predictions from others.", note: "Talks are expected to continue."),
                            TargetExpression(text: "Headline → sentence", meaning: "Expand dropped words.", note: "“Man rescues cat” = A man has rescued a cat.")],
                situation: "You brief a colleague on this morning's news: expand three headlines into full sentences and attribute every claim you can't verify.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Expand the headline: “Bridge reopened”.", expected: ["The bridge has been reopened."], focus: "headline → sentence", watch: "Add the dropped words: has been + participle."),
                                PracticeQuestion(prompt: "Report unverified costs. (it / believe)", expected: ["It is believed that costs will fall."], focus: "attribution", watch: "It is believed protects the speaker."),
                                PracticeQuestion(prompt: "Attribute a number to its source. (report)", expected: ["According to the report, sales fell by 10%."], focus: "according to", watch: "according to names the source."),
                                PracticeQuestion(prompt: "Report what people think about the minister. (thought / delay)", expected: ["The minister is thought to favour delays."], focus: "is thought to", watch: "is thought to have + participle for past acts."),
                                PracticeQuestion(prompt: "Report expected talks.", expected: ["Talks are expected to continue."], focus: "are expected to", watch: "Passive prediction: nobody predicts, it is expected.")]),
                exercises: [
                            Exercise(id: "en-foundations-media-news-language-e1", kind: "choice", prompt: "The road ___ closed since March.", options: ["has been", "is been", "was being", "had being"], answers: ["has been"], explain: "Present perfect passive: has been closed."),
                            Exercise(id: "en-foundations-media-news-language-e2", kind: "gap", prompt: "It is ___ that costs will fall. (believe)", options: [], answers: ["believed"], explain: "It is believed that…"),
                            Exercise(id: "en-foundations-media-news-language-e3", kind: "order", prompt: "Expand the headline.", options: [], answers: ["The bridge has been reopened after repairs"], explain: "has been + participle + detail."),
                            Exercise(id: "en-foundations-media-news-language-e4", kind: "written", prompt: "Attribute the fall to the report.", options: [], answers: ["according to the report sales fell", "sales fell according to the report"], explain: "according to + source.")], skills: ["grammar:passive-intro", "grammar:present-perfect", "grammar:relative-clauses", "function:express-opinion"], canDo: ["express-opinion"], prerequisites: ["grammar:past-simple-regular"]),
            Lesson(id: "en-foundations-media-opinion-pieces", title: "Opinion pieces", goal: "Build a written argument: claim, support, concession, rebuttal.",
                intro: LessonIntro(explanation: [
                            "The four-move structure: claim (“Remote work is here to stay”), support (evidence), concession (“Admittedly, not every job…”), rebuttal (“But the trend is clear”).",
                            "Concession words buy credibility: admittedly, granted, while it's true that… — you look fair before you disagree.",
                            "Endings circle back: “For all its flaws, the evidence points one way.” Repeat the claim, changed by everything before it."], examples: [
                            ExampleLine(text: "Remote work is here to stay.", meaning: "The claim — short and bare."),
                            ExampleLine(text: "Studies show a 13% productivity rise.", meaning: "Support with numbers."),
                            ExampleLine(text: "Admittedly, not every job can be remote.", meaning: "The concession."),
                            ExampleLine(text: "But the trend is unmistakable.", meaning: "The rebuttal."),
                            ExampleLine(text: "For all its flaws, the evidence points one way.", meaning: "The circular close.")]),
                expressions: [
                            TargetExpression(text: "The claim: …", meaning: "State it bare.", note: "One sentence, no hedging yet."),
                            TargetExpression(text: "Support: studies show / data suggests", meaning: "Bring evidence.", note: "Numbers beat adjectives."),
                            TargetExpression(text: "Admittedly, … / Granted, …", meaning: "Concede fairly.", note: "Fairness buys trust."),
                            TargetExpression(text: "But / However, …", meaning: "Rebut.", note: "But the core point stands."),
                            TargetExpression(text: "For all its flaws, …", meaning: "Circle back.", note: "The claim, transformed.")],
                situation: "You draft a 120-word opinion piece on four-day weeks: claim, one piece of support, one fair concession, one rebuttal, one close.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "State your claim about four-day weeks. (here to stay)", expected: ["Four-day weeks are here to stay."], focus: "the claim", watch: "Short. Bare. Debatable."),
                                PracticeQuestion(prompt: "Add one number as support.", expected: ["Trials report a 13% productivity rise."], focus: "support", watch: "A number does the arguing for you."),
                                PracticeQuestion(prompt: "Concede fairly: not every job. (admittedly)", expected: ["Admittedly, not every job can be done remotely."], focus: "the concession", watch: "admittedly + the strongest counter-case."),
                                PracticeQuestion(prompt: "Rebut the concession. (but / trend)", expected: ["But the trend is unmistakable."], focus: "the rebuttal", watch: "However also works — but is punchier."),
                                PracticeQuestion(prompt: "Close by circling back.", expected: ["For all its flaws, the evidence points one way."], focus: "the close", watch: "The claim returns, stronger.")]),
                exercises: [
                            Exercise(id: "en-foundations-media-opinion-pieces-e1", kind: "choice", prompt: "___ not every job can be remote, the trend is clear.", options: ["Admittedly", "Because", "So", "Unless"], answers: ["Admittedly"], explain: "admittedly concedes before rebutting."),
                            Exercise(id: "en-foundations-media-opinion-pieces-e2", kind: "gap", prompt: "Studies ___ a 13% productivity rise. (show)", options: [], answers: ["show"], explain: "studies show + number."),
                            Exercise(id: "en-foundations-media-opinion-pieces-e3", kind: "order", prompt: "The circular close.", options: [], answers: ["For all its flaws the evidence points one way"], explain: "for all its flaws + claim."),
                            Exercise(id: "en-foundations-media-opinion-pieces-e4", kind: "written", prompt: "State your claim about four-day weeks.", options: [], answers: ["four-day weeks are here to stay", "four day weeks are here to stay"], explain: "Short, bare, debatable.")], skills: ["writing:argument", "grammar:connectors", "function:express-opinion", "speaking:justify-opinion", "vocab:work"], canDo: ["express-opinion"], prerequisites: ["grammar:first-conditional"])])
}

public enum EnFoundationsNuance {
    public static let unit: CourseUnit = CourseUnit(id: "en-foundations-nuance", title: "Nuance & register", subtitle: "Say it the better way", level: "C1", themes: [
                    ConversationTheme("formal-swap", "The register swap", "Same idea, different room", "arrow.triangle.swap", "Course", "You rephrase the same message for different audiences: a friend, a client, a complaint, a keynote.", 0),
                    ConversationTheme("idiom-lab", "The idiom lab", "Sound natural", "text.bubble", "Course", "You upgrade literal sentences with natural chunks and idioms — carefully, one at a time.", 1)], lessons: [
            Lesson(id: "en-foundations-nuance-register", title: "Register: formal vs informal", goal: "Rephrase the same message for different audiences and levels of formality.",
                intro: LessonIntro(explanation: [
                            "Informal leans on phrasal verbs and contractions: “We'll set up a call.” Formal prefers single verbs: “We will arrange a call.”",
                            "Requests climb the ladder of politeness: “Send it” → “Can you send it?” → “Could you send it?” → “I would be grateful if you could send it.”",
                            "Written formality also changes vocabulary: get → receive, help → assistance, but → however, kids → children."], examples: [
                            ExampleLine(text: "We'll set up a call tomorrow. (informal)", meaning: "Phrasal + contraction."),
                            ExampleLine(text: "We will arrange a call tomorrow. (formal)", meaning: "Single verb, no contraction."),
                            ExampleLine(text: "Can you send the invoice?", meaning: "Neutral request."),
                            ExampleLine(text: "I would be grateful if you could send the invoice.", meaning: "Formal request."),
                            ExampleLine(text: "Sorry, that doesn't work for me. (informal)", meaning: "Soft refusal."),
                            ExampleLine(text: "Unfortunately, that arrangement is not feasible. (formal)", meaning: "Formal refusal.")]),
                expressions: [
                            TargetExpression(text: "set up vs arrange", meaning: "Phrasal informal, single verb formal.", note: "Same meaning, different room."),
                            TargetExpression(text: "I would be grateful if you could …", meaning: "The formal request.", note: "Emails, clients, institutions."),
                            TargetExpression(text: "Unfortunately, … is not feasible.", meaning: "The formal no.", note: "feasible = possible/viable."),
                            TargetExpression(text: "get → receive", meaning: "Upgrade everyday verbs.", note: "We received your message."),
                            TargetExpression(text: "kids → children", meaning: "Register-sensitive nouns.", note: "Formal writing avoids kids."),
                            TargetExpression(text: "Sorry about that → I apologise for the inconvenience.", meaning: "Apology ladder.", note: "Match the damage.")],
                situation: "One message, three rooms: say the same cancellation to a friend, then to a client, then in a formal complaint — and feel the register move.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Say informally that you'll organise a call.", expected: ["I'll set up a call.", "We'll set up a call."], focus: "informal register", watch: "Phrasal verbs + contractions are the informal markers."),
                                PracticeQuestion(prompt: "Now say it formally. (arrange)", expected: ["We will arrange a call.", "I will arrange a call."], focus: "formal register", watch: "Single verb, no contraction."),
                                PracticeQuestion(prompt: "Make this formal: “Can you send the report?”", expected: ["I would be grateful if you could send the report.", "Could you please send the report?"], focus: "request ladder", watch: "would be grateful is the top rung for email."),
                                PracticeQuestion(prompt: "Refuse formally: the arrangement doesn't work.", expected: ["Unfortunately, that arrangement is not feasible.", "Unfortunately, we are unable to accept the arrangement."], focus: "formal refusal", watch: "Formal refusals start with unfortunately and avoid contractions."),
                                PracticeQuestion(prompt: "Make this formal: “Sorry about the delay.”", expected: ["I apologise for the delay.", "Please accept my apologies for the delay."], focus: "apology ladder", watch: "Match formality to the damage."),
                                PracticeQuestion(prompt: "Spot the register: “We received your message” vs “We got your message”.", expected: ["we received your message is formal", "we got your message is informal"], focus: "get vs receive", watch: "Same meaning; receive belongs to formal writing.")]),
                exercises: [
                            Exercise(id: "en-foundations-nuance-register-e1", kind: "choice", prompt: "Which is the FORMAL request?", options: ["I would be grateful if you could reply.", "Can you reply?", "Reply please.", "Reply when you can!"], answers: ["I would be grateful if you could reply."], explain: "would be grateful marks formal register."),
                            Exercise(id: "en-foundations-nuance-register-e2", kind: "gap", prompt: "Formal single verb: We will ___ a meeting. (phrasal: set up)", options: [], answers: ["arrange", "organise", "organize"], explain: "set up → arrange/organise."),
                            Exercise(id: "en-foundations-nuance-register-e3", kind: "order", prompt: "Formal apology.", options: [], answers: ["I apologise for the inconvenience"], explain: "The formal apology formula."),
                            Exercise(id: "en-foundations-nuance-register-e4", kind: "written", prompt: "Make it formal: “We got your email.”", options: [], answers: ["we received your email", "we have received your email"], explain: "get → receive.")], skills: ["vocab:social-expressions", "function:negotiate", "writing:email", "function:talk-about-work"], canDo: ["talk-about-work"], prerequisites: ["grammar:connectors", "grammar:modal-must-have-to"]),
            Lesson(id: "en-foundations-nuance-chunks", title: "Natural chunks", goal: "Replace literal sentences with natural chunks and idioms — precisely, not decoratively.",
                intro: LessonIntro(explanation: [
                            "Chunks are ready-made phrases native speakers reach for: “It depends.” “That makes sense.” “As far as I know…” “I'm not sure about that.”",
                            "Idioms carry culture and risk: “It's a grey area” is safe and useful; rare or dated idioms can sound costume-y. One per conversation is plenty.",
                            "Upgrading literal speech: “I don't decide yet” → “I'm still on the fence.” The chunk must match the meaning exactly."], examples: [
                            ExampleLine(text: "It depends on the weather.", meaning: "The universal answer chunk."),
                            ExampleLine(text: "That makes sense.", meaning: "Accepting an explanation."),
                            ExampleLine(text: "As far as I know, the flight is on time.", meaning: "Limited certainty."),
                            ExampleLine(text: "I'm still on the fence.", meaning: "Undecided."),
                            ExampleLine(text: "It's a bit of a grey area.", meaning: "Not clearly one thing or the other."),
                            ExampleLine(text: "Let's play it by ear.", meaning: "Decide as things happen.")]),
                expressions: [
                            TargetExpression(text: "It depends.", meaning: "Conditional answer.", note: "…on + factor: on the price."),
                            TargetExpression(text: "That makes sense.", meaning: "Understanding confirmed.", note: "Never “it has sense”."),
                            TargetExpression(text: "As far as I know, …", meaning: "Soften a claim.", note: "Knowledge may be incomplete."),
                            TargetExpression(text: "I'm on the fence.", meaning: "No decision yet.", note: "Sitting between two options."),
                            TargetExpression(text: "a grey area", meaning: "Unclear rules or meaning.", note: "The law here is a grey area."),
                            TargetExpression(text: "play it by ear", meaning: "Improvise the plan.", note: "No fixed script.")],
                situation: "You coach a colleague before a difficult meeting: swap their literal lines for natural chunks — and decide which idioms to avoid.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Answer naturally when asked if remote work is better.", expected: ["It depends.", "It depends on the job."], focus: "it depends", watch: "“It depends of” — English takes on."),
                                PracticeQuestion(prompt: "Confirm you understood the explanation.", expected: ["That makes sense."], focus: "makes sense", watch: "Never “it has sense” — the chunk is makes sense."),
                                PracticeQuestion(prompt: "Soften a claim about tomorrow's schedule.", expected: ["As far as I know, it's free.", "As far as I know, the schedule hasn't changed."], focus: "limited certainty", watch: "The chunk admits your knowledge might be incomplete."),
                                PracticeQuestion(prompt: "Say you haven't decided between the two offers.", expected: ["I'm still on the fence."], focus: "undecided", watch: "The fence sits between two options — that's the image."),
                                PracticeQuestion(prompt: "Say the rule is unclear. (idiom)", expected: ["It's a bit of a grey area.", "It's a grey area."], focus: "grey area", watch: "grey (BrE) or gray (AmE) — both fine."),
                                PracticeQuestion(prompt: "Say you'll decide as things happen. (idiom)", expected: ["Let's play it by ear.", "We'll play it by ear."], focus: "play it by ear", watch: "ear, not year — it comes from music.")]),
                exercises: [
                            Exercise(id: "en-foundations-nuance-chunks-e1", kind: "choice", prompt: "Which chunk means “no decision yet”?", options: ["I'm on the fence.", "It's a grey area.", "It depends.", "That makes sense."], answers: ["I'm on the fence."], explain: "On the fence = between two options, undecided."),
                            Exercise(id: "en-foundations-nuance-chunks-e2", kind: "gap", prompt: "That ___ sense — thanks for explaining.", options: [], answers: ["makes"], explain: "makes sense, never has sense."),
                            Exercise(id: "en-foundations-nuance-chunks-e3", kind: "order", prompt: "Soften your claim about the flight.", options: [], answers: ["As far as I know the flight is on time"], explain: "as far as I know + the claim."),
                            Exercise(id: "en-foundations-nuance-chunks-e4", kind: "written", prompt: "Fix: “It depends of the price.”", options: [], answers: ["it depends on the price"], explain: "depend on + factor.")], skills: ["vocab:social-expressions", "function:express-opinion", "speaking:sustained-conversation", "writing:argument"], canDo: ["express-opinion"], prerequisites: ["grammar:connectors"]),
            Lesson(id: "en-foundations-nuance-hedging", title: "Hedging & precision", goal: "Fine-tune opinions: soften, intensify and qualify like a confident speaker.",
                intro: LessonIntro(explanation: [
                            "Hedging protects accuracy: “tends to”, “to some extent”, “arguably”, “in most cases”. Strong claims need strong evidence — otherwise hedge.",
                            "Intensifiers scale: slightly < rather < considerably < far. “Far more efficient” is stronger than “slightly more efficient”.",
                            "Precision beats intensity: “a threefold increase” > “a lot more”. Numbers, examples and scope (“in this case”) make opinions defensible."], examples: [
                            ExampleLine(text: "This approach tends to work better.", meaning: "A hedged claim."),
                            ExampleLine(text: "To some extent, I agree.", meaning: "Partial agreement."),
                            ExampleLine(text: "Arguably, it's the best option on the table.", meaning: "Opinion with room."),
                            ExampleLine(text: "The new version is far more stable.", meaning: "A strong, clear difference."),
                            ExampleLine(text: "Costs fell by roughly a third.", meaning: "Precision with a number."),
                            ExampleLine(text: "In this specific case, I'd wait.", meaning: "Scope limiting.")]),
                expressions: [
                            TargetExpression(text: "tends to + verb", meaning: "General pattern, not law.", note: "Prices tend to rise in summer."),
                            TargetExpression(text: "to some extent / to a degree", meaning: "Partial truth.", note: "Agreement with reservations."),
                            TargetExpression(text: "arguably", meaning: "Defensible opinion.", note: "Arguably the best paella in town."),
                            TargetExpression(text: "slightly / rather / considerably / far", meaning: "The intensity scale.", note: "far > considerably > rather > slightly."),
                            TargetExpression(text: "by roughly a third", meaning: "Approximate precision.", note: "roughly, about, approximately."),
                            TargetExpression(text: "in this specific case", meaning: "Limit the scope.", note: "No universal claims.")],
                situation: "You present an opinion to a skeptical audience: claim, hedge, quantify and limit scope — then defend it once challenged.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Hedge a claim about remote productivity.", expected: ["Remote work tends to increase productivity.", "It tends to work better for focused tasks."], focus: "tends to", watch: "tends to + base verb softens the pattern without killing it."),
                                PracticeQuestion(prompt: "Agree, but only partly.", expected: ["To some extent, I agree.", "I agree to a degree."], focus: "partial agreement", watch: "The quantifier keeps the disagreement alive."),
                                PracticeQuestion(prompt: "Give a defensible superlative opinion about a restaurant.", expected: ["Arguably, it's the best ramen in the city."], focus: "arguably", watch: "arguably signals: I can defend this."),
                                PracticeQuestion(prompt: "Rank the intensifiers: slightly / far / rather. (weakest to strongest)", expected: ["slightly, rather, far"], focus: "intensity scale", watch: "slightly < rather < considerably < far."),
                                PracticeQuestion(prompt: "Be precise about a cost drop: from 90 to 60. (roughly)", expected: ["Costs fell by roughly a third."], focus: "approximate numbers", watch: "roughly + fraction beats “a lot less”."),
                                PracticeQuestion(prompt: "Limit your advice so it isn't universal.", expected: ["In this specific case, I'd wait.", "In this case, I'd wait before deciding."], focus: "scope", watch: "in this case protects the advice from other contexts.")]),
                exercises: [
                            Exercise(id: "en-foundations-nuance-hedging-e1", kind: "choice", prompt: "Which claim is the most hedged?", options: ["It tends to work better.", "It always works.", "It works.", "It never fails."], answers: ["It tends to work better."], explain: "tends to is the hedged pattern claim."),
                            Exercise(id: "en-foundations-nuance-hedging-e2", kind: "gap", prompt: "The new engine is ___ more efficient. (strongest intensifier)", options: [], answers: ["far", "considerably"], explain: "far (or considerably) is stronger than slightly."),
                            Exercise(id: "en-foundations-nuance-hedging-e3", kind: "order", prompt: "Give a partial agreement.", options: [], answers: ["To some extent I agree"], explain: "to some extent + I agree."),
                            Exercise(id: "en-foundations-nuance-hedging-e4", kind: "written", prompt: "Fix: “It depends of the context.”", options: [], answers: ["it depends on the context"], explain: "depend on — the preposition is on.")], skills: ["grammar:connectors", "function:express-opinion", "speaking:justify-opinion", "writing:argument"], canDo: ["express-opinion"], prerequisites: ["grammar:connectors"]),
            Lesson(id: "en-foundations-nuance-academic", title: "The academic voice", goal: "State positions in academic and professional registers: impersonal, evidenced, measured.",
                intro: LessonIntro(explanation: [
                            "The academic voice removes the “I”: “This paper argues that…”, “The data suggests…”, “It has been observed that…”. The claim carries the sentence, not the person.",
                            "Evidence verbs scale certainty: demonstrate > suggest > indicate > appear to. Choose the verb that matches the strength of your data.",
                            "Structure is visible: “First… Second… Taken together, these findings…” — the reader should always know where they are."], examples: [
                            ExampleLine(text: "This paper argues that hybrid models outperform either extreme.", meaning: "The thesis sentence."),
                            ExampleLine(text: "The data suggests a modest effect.", meaning: "suggests = careful."),
                            ExampleLine(text: "The results demonstrate a clear correlation.", meaning: "demonstrate = strong evidence."),
                            ExampleLine(text: "It has been observed that remote teams innovate differently.", meaning: "Impersonal passive reporting."),
                            ExampleLine(text: "Taken together, these findings point to a structural cause.", meaning: "Synthesis marker."),
                            ExampleLine(text: "Further research is needed to confirm the effect.", meaning: "The classic closing hedge.")]),
                expressions: [
                            TargetExpression(text: "This paper/chapter argues that …", meaning: "State the thesis.", note: "argue = defend a position."),
                            TargetExpression(text: "The data suggests / demonstrates …", meaning: "Certainty scaled to evidence.", note: "Choose the honest verb."),
                            TargetExpression(text: "It has been observed that …", meaning: "Impersonal reporting.", note: "Passive keeps the I out."),
                            TargetExpression(text: "Taken together, …", meaning: "Synthesise several points.", note: "Ends the middle, opens the close."),
                            TargetExpression(text: "Further research is needed …", meaning: "The honest limit.", note: "Every study ends here."),
                            TargetExpression(text: "with respect to / regarding", meaning: "Formal topic shifts.", note: "Regarding costs, the picture differs.")],
                situation: "You present a controversial finding to a skeptical panel: thesis, evidence verbs that match your data, visible structure and an honest limit.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "State your thesis formally. (hybrid models outperform)", expected: ["This paper argues that hybrid models outperform either extreme."], focus: "thesis", watch: "argues that + full clause — the position, not the topic."),
                                PracticeQuestion(prompt: "Your evidence is moderate. Choose the verb. (the data / a modest effect)", expected: ["The data suggests a modest effect."], focus: "scaled verbs", watch: "demonstrates would overclaim; suggests is honest."),
                                PracticeQuestion(prompt: "Your evidence is strong. Choose the verb. (clear correlation)", expected: ["The results demonstrate a clear correlation."], focus: "scaled verbs", watch: "With strong data, demonstrates is the honest choice."),
                                PracticeQuestion(prompt: "Report an observation without saying who observed it.", expected: ["It has been observed that remote teams innovate differently."], focus: "impersonal passive", watch: "It + has been + participle keeps the voice out."),
                                PracticeQuestion(prompt: "Synthesise two findings into one conclusion.", expected: ["Taken together, these findings point to a structural cause."], focus: "synthesis", watch: "Taken together announces the synthesis."),
                                PracticeQuestion(prompt: "Close with the honest limit of the study.", expected: ["Further research is needed to confirm the effect."], focus: "the limit", watch: "Every credible study admits its edge.")]),
                exercises: [
                            Exercise(id: "en-foundations-nuance-academic-e1", kind: "choice", prompt: "The data ___ a modest effect. (moderate evidence)", options: ["suggests", "demonstrates", "proves", "ignores"], answers: ["suggests"], explain: "Moderate evidence takes suggests, not demonstrates."),
                            Exercise(id: "en-foundations-nuance-academic-e2", kind: "gap", prompt: "It has ___ observed that remote teams innovate differently.", options: [], answers: ["been"], explain: "Impersonal passive: has been + participle."),
                            Exercise(id: "en-foundations-nuance-academic-e3", kind: "order", prompt: "State the thesis.", options: [], answers: ["This paper argues that hybrid models outperform either extreme"], explain: "This paper argues that + claim."),
                            Exercise(id: "en-foundations-nuance-academic-e4", kind: "written", prompt: "Close the study honestly.", options: [], answers: ["further research is needed to confirm the effect", "further research is needed"], explain: "The classic honest close.")], skills: ["writing:argument", "grammar:passive-intro", "function:express-opinion", "function:talk-about-work", "grammar:connectors"], canDo: ["express-opinion"], prerequisites: ["grammar:passive-intro", "grammar:connectors"]),
            Lesson(id: "en-foundations-nuance-presenting", title: "Presenting with confidence", goal: "Signpost a talk, land key points and handle questions without losing your footing.",
                intro: LessonIntro(explanation: [
                            "Signposts keep audiences aboard: “I'll start with…”, “That brings me to…”, “So, to sum up…”. Say where you are; nobody resents a map.",
                            "Land key points with a pause and a restatement: “The one thing to remember is this.” Silence sells importance.",
                            "Hard questions get a frame: “That's exactly the point — my answer is twofold.” Buying structure, not stalling."], examples: [
                            ExampleLine(text: "I'll start with why this matters.", meaning: "The opening signpost."),
                            ExampleLine(text: "That brings me to the results.", meaning: "The transition."),
                            ExampleLine(text: "The one thing to remember is this.", meaning: "Point-landing phrase."),
                            ExampleLine(text: "So, to sum up: three findings, one conclusion.", meaning: "The summary signpost."),
                            ExampleLine(text: "That's exactly the point — and my answer is twofold.", meaning: "Handling the hard question.")]),
                expressions: [
                            TargetExpression(text: "I'll start with …", meaning: "Open the map.", note: "I'll start with the problem."),
                            TargetExpression(text: "That brings me to …", meaning: "Transition.", note: "…to the second point."),
                            TargetExpression(text: "The one thing to remember is …", meaning: "Land the point.", note: "Then pause. Let it sit."),
                            TargetExpression(text: "So, to sum up …", meaning: "Signal the close.", note: "Repeat the three parts."),
                            TargetExpression(text: "That's exactly the point.", meaning: "Own the hard question.", note: "Then answer in two parts."),
                            TargetExpression(text: "I'm glad you asked that.", meaning: "Buy a second, kindly.", note: "Use sparingly — overdone it's a cliché.")],
                situation: "You present a small project to a skeptical room: signpost the three parts, land one key sentence and survive two tough questions.",
                practice: LessonPractice(questions: [
                                PracticeQuestion(prompt: "Open your talk by announcing the first part.", expected: ["I'll start with why this matters.", "I'll start with the problem."], focus: "opening signpost", watch: "I'll start with + noun: “I'll start with to explain” is wrong."),
                                PracticeQuestion(prompt: "Move from findings to recommendations.", expected: ["That brings me to my recommendations."], focus: "transition", watch: "brings me to + noun: the signpost is the map."),
                                PracticeQuestion(prompt: "Land your single key message.", expected: ["The one thing to remember is this: focus beats time."], focus: "landing", watch: "Say it, then stop talking. The pause is the emphasis."),
                                PracticeQuestion(prompt: "Signal you are closing.", expected: ["So, to sum up: three findings, one conclusion."], focus: "the close", watch: "to sum up + the structure you promised at the start."),
                                PracticeQuestion(prompt: "Handle a hostile question confidently.", expected: ["That's exactly the point — and my answer is twofold."], focus: "hard questions", watch: "Own the question, then give structure: first… second…")]),
                exercises: [
                            Exercise(id: "en-foundations-nuance-presenting-e1", kind: "gap", prompt: "I'll ___ ___ why this matters. (2 words)", options: [], answers: ["start with"], explain: "I'll start with + noun."),
                            Exercise(id: "en-foundations-nuance-presenting-e2", kind: "gap", prompt: "That ___ me to my second point.", options: [], answers: ["brings"], explain: "That brings me to…"),
                            Exercise(id: "en-foundations-nuance-presenting-e3", kind: "order", prompt: "Signal the summary.", options: [], answers: ["So to sum up three findings one conclusion"], explain: "So, to sum up: …"),
                            Exercise(id: "en-foundations-nuance-presenting-e4", kind: "written", prompt: "Own a hostile question before answering.", options: [], answers: ["thats exactly the point", "that is exactly the point"], explain: "That's exactly the point — then structure.")], skills: ["function:talk-about-work", "speaking:sustained-conversation", "grammar:connectors", "vocab:work"], canDo: ["talk-about-work"], prerequisites: ["grammar:connectors"])])
}

public enum EnCareU1 {
