                            Exercise(id: "en-work-u1-meetings-e4", kind: "written", prompt: "Say what blocks you: the client's approval.", options: [], answers: ["i'm blocked on the client's approval", "i am blocked on the approval", "i'm blocked by the client's approval"], explain: "blocked on/by + the thing.")], skills: ["function:talk-about-work", "grammar:past-simple-regular", "grammar:present-continuous", "function:make-requests", "speaking:sustained-conversation"], canDo: ["talk-about-work"], prerequisites: ["grammar:present-simple", "grammar:present-continuous"]),
            Lesson(id: "en-work-u1-emails", title: "Professional emails", goal: "Write short professional emails: request, confirm and follow up.",
