                exercises: [
                            Exercise(id: "fr-foundations-u9-nuances-e1", kind: "choice", prompt: "___ mon sens, la mesure arrive trop tôt.", options: ["À", "Par", "Dans", "Chez"], answers: ["À"], explain: "À mon sens : opinion réfléchie, accent grave."),
